'use strict';
let DATA={profiles:[],events:[],sources:[],entities:[],communityItems:[],videoItems:[],insights:[],meta:{},youtube:{accounts:[],videos:[],gaps:[],meta:{}},activity:{records:[],meta:{}},services:[],discovery:{meta:{},people:[],records:[],queries:[],gaps:[]}}, sourceMap=new Map(), profileMap=new Map();
const main=document.querySelector('main'),dialog=document.querySelector('#detail'),dialogBody=document.querySelector('#dialog-body');
const state={search:'',filter:'',year:''};let currentView='overview',returnRoute='#/profiles',changingDialog=false;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arr=v=>Array.isArray(v)?v:v?[v]:[];
const plain=v=>typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');
const text=v=>esc(plain(v));
const url=v=>/^https?:\/\//i.test(String(v||''))?esc(v):'#';
const date=v=>!v?'Date not established':/^\d{4}-\d{2}-\d{2}$/.test(v)?new Date(v+'T12:00:00Z').toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}):esc(v);
const unique=v=>[...new Set(v.filter(Boolean))].sort((a,b)=>String(a).localeCompare(String(b)));
function refs(ids){return arr(ids).filter(id=>sourceMap.has(id)).map(id=>{const s=sourceMap.get(id);return `<a class="citation" href="#/sources/${encodeURIComponent(id)}" title="${esc(s.title)}">[${String(s.index).padStart(2,'0')}] ${esc(s.publisher||'Source')}</a>`}).join('')}
function citations(ids){const x=refs(ids);return x?`<div class="citation-row" aria-label="Supporting sources">${x}</div>`:''}
function tags(v){return `<div class="tags">${arr(v).slice(0,5).map(x=>`<span class="tag">${text(x)}</span>`).join('')}</div>`}
function ul(v){return `<ul>${arr(v).map(x=>`<li>${text(x)}</li>`).join('')}</ul>`}
function intro(label,title,description){return `<header class="page-intro"><span class="eyebrow">${esc(label)}</span><h1>${title}</h1><p>${description}</p></header>`}
function empty(message='Try a broader search or choose a different filter.'){return `<div class="empty"><h3>No matching records</h3><p>${message}</p></div>`}
function controls(placeholder,options,label,yearOptions){return `<div class="tools"><label class="search-wrap"><span class="sr-only">${esc(placeholder)}</span><input type="search" id="search" placeholder="${esc(placeholder)}" value="${esc(state.search)}" aria-label="${esc(placeholder)}"></label>${options?`<select id="filter" aria-label="${esc(label)}"><option value="">All ${esc(label.toLowerCase())}</option>${options.map(x=>`<option value="${esc(x)}" ${state.filter===x?'selected':''}>${esc(x)}</option>`).join('')}</select>`:''}${yearOptions?`<select id="year" aria-label="Timeline period"><option value="">All periods</option>${yearOptions.map(x=>`<option value="${x}" ${state.year===x?'selected':''}>${x}s</option>`).join('')}</select>`:''}<span class="result-count" id="result-count" role="status"></span></div><div id="results"></div>`}
function matches(v){return !state.search||JSON.stringify(v).toLowerCase().includes(state.search.toLowerCase())}
function count(n,total){const target=document.querySelector('#result-count');if(target)target.textContent=`${n} of ${total} records`}
function feature(p,i){if(!p)return '';return `<a class="feature" href="#/profiles/${encodeURIComponent(p.id)}"><span class="feature-number">0${i+1}</span><span class="badge">${esc(['Bashar','Ashtar','Ryokah'][i]||p.entity)}</span><h3>${esc(p.channeler||p.name)}</h3><p class="feature-copy">${esc(p.summary).slice(0,210)}${p.summary?.length>210?'…':''}</p><div class="feature-bottom"><span>${p.firstDate?date(p.firstDate)+' · '+esc(p.datePrecision||'dated record'):'Onset remains unresolved'}</span><span aria-hidden="true">↗</span></div></a>`}
function overview(){const featured=['ba-bashar','ar-athina-ashtar','ar-ryok'].map(x=>profileMap.get(x));main.innerHTML=`<section class="hero"><div><span class="eyebrow">PEOPLE · CLAIMED ENTITIES · HISTORICAL RECORDS</span><h1>Tracing voices.<br>Following <em>the sources.</em></h1><p class="hero-description">From the Ra material to Bashar, Ashtar and Ryokah. Explore the people, traditions and communities behind modern channeling.</p><div class="hero-actions"><a class="button" href="#/discovery">Explore expanded index <span>↗</span></a><a class="text-link" href="#/timeline">Follow the timeline</a></div></div><div class="orbit-wrap"><div class="orbit"><svg viewBox="0 0 470 400" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width=".8"><ellipse cx="235" cy="180" rx="205" ry="130" transform="rotate(-24 235 180)"/><ellipse cx="235" cy="180" rx="164" ry="180" transform="rotate(40 235 180)"/><ellipse cx="235" cy="180" rx="102" ry="166" transform="rotate(-41 235 180)"/><circle cx="235" cy="180" r="90" stroke-dasharray="2 6"/><path d="M235 10V350M50 180H430" stroke-dasharray="2 8"/></g></svg><div class="orbit-center">People &<br>their stories</div>${['hr-ra','ba-bashar','ar-athina-ashtar','ar-ryok'].map((id,i)=>`<a class="orbit-node n${i}" href="#/profiles/${id}">${['Ra / Law of One','Bashar / Darryl Anka','Ashtar / Athina Król','Ryokah / Tyler Ellison'][i]}</a>`).join('')}</div><p class="orbit-caption">A conceptual map · not an astronomical chart</p></div></section><section class="stat-strip" aria-label="Research collection"><div class="stat"><b>${DATA.profiles.length}</b><span>People &<br>channeling profiles</span></div><div class="stat"><b>${DATA.events.length}</b><span>Documentary<br>timeline entries</span></div><div class="stat"><b>${DATA.sources.length}</b><span>Linked<br>source records</span></div><div class="stat"><b>${DATA.communityItems.length}</b><span>Community<br>discussions</span></div></section>${youtubeOverview()}${discoveryOverview()}<section class="section"><div class="section-heading"><div><span class="eyebrow">THREE FOCAL THREADS</span><h2>Meet the channels.</h2></div><p>Start with the human voice. Then follow the attributed speaker, the claimed origin and the original record.</p></div><div class="feature-grid">${featured.map(feature).join('')}</div><article class="archive-feature"><div><span class="eyebrow">THE STARTING ARCHIVE</span><h2>Ra. The Law of One.</h2><a class="text-link" href="#/profiles/hr-ra">Open the Ra record ↗</a></div><div class="archive-right"><div class="archive-dates">1981 → 1984<span>106 NUMBERED SESSIONS</span></div><p>The Ra archive offers a dated entry point into channeling literature. The broader timeline also follows earlier Spiritualist, contactee and Seth records.</p><div style="margin-top:17px"><a class="text-link" href="#/timeline">See the historical context ↗</a></div></div></article></section><section class="section"><div class="section-heading"><div><span class="eyebrow">READING BETWEEN THE RECORDS</span><h2>What the research reveals.</h2></div></div><div class="insight-grid">${DATA.insights.map(x=>`<article class="insight"><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p>${citations(x.sourceIds)}</article>`).join('')}</div></section><aside class="reading-note"><p><strong>Read claims with their context.</strong> A published session documents what was said. It does not by itself verify extraterrestrial contact, an entity’s identity or healing outcomes.</p><a href="#/method">Read the method ↗</a></aside>`}
function profiles(){main.innerHTML=intro('THE PEOPLE BEHIND THE VOICES','People & channels','A curated directory of public practitioners and archives. Each record separates biography, attributed speaker, teachings, chronology and unresolved questions.')+controls('Search names, entities, themes…',unique(DATA.profiles.map(x=>x.classification)),'Classifications');refreshProfiles()}
function refreshProfiles(){const rows=DATA.profiles.filter(x=>matches(x)&&(!state.filter||x.classification===state.filter));document.querySelector('#results').innerHTML=rows.length?`<div class="profile-list">${rows.map(p=>`<article class="profile-card"><span class="badge">${esc(p.entity||'Channeling tradition')}</span><h3><a href="#/profiles/${encodeURIComponent(p.id)}" style="text-decoration:none">${esc(p.name)}</a></h3><div class="meta">${p.firstDate?date(p.firstDate)+' · '+esc(p.datePrecision||'reported date'):'First date not established'}</div><p>${esc(p.summary)}</p>${tags(p.themes)}${citations(p.sourceIds)}<a class="card-link" href="#/profiles/${encodeURIComponent(p.id)}">Read the full profile <span aria-hidden="true">↗</span></a></article>`).join('')}</div>`:empty();count(rows.length,DATA.profiles.length)}
function timeline(){main.innerHTML=intro('DOCUMENTS, NOT COSMIC TIME','A history of the record.','Start at Ra in 1981, or trace the earlier context. Dates identify reported experiences, sessions, publications and discussions. They do not date the existence of a claimed entity.')+`<p style="margin-bottom:22px"><a class="text-link" href="#/profiles/hr-ra">Ra archive: January 15, 1981 to March 15, 1984 ↗</a></p>`+controls('Search events, people, traditions…',unique(DATA.events.map(x=>x.type)),'Event types',unique(DATA.events.filter(x=>/^\d{4}/.test(x.date)).map(x=>String(Math.floor(parseInt(x.date)/10)*10))));refreshTimeline()}
function refreshTimeline(){const rows=DATA.events.filter(x=>matches(x)&&(!state.filter||x.type===state.filter)&&(!state.year||Math.floor(parseInt(x.date)/10)*10===Number(state.year))).sort((a,b)=>String(a.date||'9999').localeCompare(String(b.date||'9999')));document.querySelector('#results').innerHTML=rows.length?`<div class="timeline">${rows.map(x=>`<article class="timeline-event"><div class="timeline-date">${date(x.date)}</div><div class="timeline-content"><span class="badge">${esc(x.type||'Documented record')}</span><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p>${citations(x.sourceIds)}</div></article>`).join('')}</div>`:empty();count(rows.length,DATA.events.length)}
function entities(){main.innerHTML=intro('A COMPARISON OF NARRATIVES','Entities & traditions','Names such as “Pleiadian,” “Essassani” and “Arcturian” belong to the sources’ own cosmologies. These groupings compare their language and relationships; they are not a verified biological taxonomy.')+controls('Search entities, traditions, claimed origins…',null);refreshEntities()}
function refreshEntities(){const rows=DATA.entities.filter(matches);document.querySelector('#results').innerHTML=rows.length?`<div class="entity-list">${rows.map(x=>`<article class="entity-card"><span class="eyebrow">${esc(x.classification)}</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><div class="entity-links">${arr(x.profileIds).map(id=>profileMap.has(id)?`<a href="#/profiles/${encodeURIComponent(id)}">${esc(profileMap.get(id).name)} ↗</a>`:'').join('')}</div>${arr(x.caveats).map(c=>`<p class="tiny">${text(c)}</p>`).join('')}${citations(x.sourceIds)}</article>`).join('')}</div>`:empty();count(rows.length,DATA.entities.length)}
function communities(){main.innerHTML=intro('PUBLIC CONVERSATIONS','Belief, doubt & discussion.','Public threads from Reddit, WizardForums and Become A Living God. Read them as samples of reception and discovery, with disagreement and access limits preserved. They do not represent whole communities.')+controls('Search threads, ideas, people…',unique(DATA.communityItems.map(x=>x.platform)),'Platforms');refreshCommunities()}
function refreshCommunities(){const rows=DATA.communityItems.filter(x=>matches(x)&&(!state.filter||x.platform===state.filter));document.querySelector('#results').innerHTML=rows.length?`<div class="record-list">${rows.map(x=>`<article class="record"><div class="record-category">${esc(x.platform)}<div class="record-date">${date(x.date)}</div></div><div><h3><a href="${url(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a></h3><p>${esc(x.summary)}</p><div class="tags"><span class="tag">${esc(x.position||'Public discussion')}</span></div><p class="tiny"><strong>Access:</strong> ${esc(x.access||'See source note')}</p>${citations(x.sourceIds)}</div><a class="external-arrow" href="${url(x.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(x.title)} in a new tab">↗</a></article>`).join('')}</div>`:empty();count(rows.length,DATA.communityItems.length)}
function videos(){main.innerHTML=intro('WATCH & LISTEN','Follow the original voices.','A curated trail through public YouTube records, creator channels and recording catalogs. Read the access note: metadata, catalog descriptions and full recordings are different kinds of evidence.')+controls('Search recordings, speakers, topics…',null);refreshVideos()}
function refreshVideos(){const rows=DATA.videoItems.filter(matches);document.querySelector('#results').innerHTML=rows.length?`<div class="record-list">${rows.map((x,i)=>`<article class="record"><div class="record-category">${String(i+1).padStart(2,'0')} / MEDIA RECORD<div class="record-date">${date(x.date)}</div></div><div><h3><a href="${url(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)}</a></h3><p>${esc(x.notes)}</p>${citations(x.sourceIds)}</div><a class="external-arrow" href="${url(x.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${esc(x.title)} in a new tab">↗</a></article>`).join('')}</div>`:empty();count(rows.length,DATA.videoItems.length)}
function sources(){main.innerHTML=intro('THE RESEARCH TRAIL','Source library.','Follow every profile and timeline entry back to its references. An official source is primary evidence for what a practitioner says, not independent confirmation of the attributed speaker.')+controls('Search titles, publishers, access notes…',unique(DATA.sources.map(x=>x.kind)),'Source types');refreshSources()}
function refreshSources(){const rows=DATA.sources.filter(x=>matches(x)&&(!state.filter||x.kind===state.filter));document.querySelector('#results').innerHTML=rows.length?`<div class="source-list">${rows.map(x=>`<article class="source-card" id="source-${esc(x.id)}"><span class="source-index">${String(x.index).padStart(2,'0')}</span><span class="source-label">${esc(x.kind||'Reference')}</span><h3><a href="#/sources/${encodeURIComponent(x.id)}">${esc(x.title)}</a></h3><p>${esc(x.publisher)} · ${date(x.date)}</p>${x.notes?`<p style="margin-top:12px">${text(x.notes)}</p>`:''}<a class="source-url" href="${url(x.url)}" target="_blank" rel="noopener noreferrer">${esc((x.url||'').replace(/^https?:\/\//,'').replace(/\/$/,''))} ↗</a></article>`).join('')}</div>`:empty();count(rows.length,DATA.sources.length)}
function method(){main.innerHTML=intro('HOW TO READ THIS ATLAS','Curiosity, with a paper trail.','This is a study of public claims, texts, identities and their reception. It keeps the experience, the interpretation and the available evidence visible together.')+`<section class="method-grid"><h2>What is included</h2><div><p>${esc(DATA.meta.scope)}</p><p>The focal path begins with the Ra archive and follows Darryl Anka / Bashar, Athina Król / Ashtar and Tyler Ellison / Ryokah. Earlier traditions provide context; other public practitioners widen the comparison.</p></div></section><section class="method-grid"><h2>Read the labels</h2><div class="definition-grid"><div class="definition"><h4>Channeler</h4><p>The human who presents a message as coming from another consciousness, collective or source.</p></div><div class="definition"><h4>Claimed entity</h4><p>The attributed speaker in the source’s own narrative. Naming it does not establish an external identity.</p></div><div class="definition"><h4>Medium</h4><p>A practitioner who may describe communication with deceased people or spirits. This is not interchangeable with an ET claim.</p></div><div class="definition"><h4>Healer</h4><p>A public spiritual-healing description. A testimonial or channeling claim does not establish medical efficacy.</p></div></div></section><section class="method-grid"><h2>Research method</h2><div><ol>${arr(DATA.meta.method).map(x=>`<li>${text(x)}</li>`).join('')}</ol></div></section><section class="method-grid"><h2>Dates mean different things</h2><div><p>A reported first experience can precede a first public session. A session date can precede a book’s publication. A YouTube upload can contain decades-old footage. The timeline keeps those distinctions in each entry’s label and description.</p><p>Unknown dates remain unknown. Dates of ancient origins given by an entity belong to its claims, not the documentary chronology.</p></div></section><section class="method-grid"><h2>Coverage & limits</h2><div>${ul(DATA.meta.limits)}</div></section><section class="method-grid"><h2>Experience & evidence</h2><div><p>Research into self-reported channeling can describe practitioners’ experiences and recurring message themes. These studies ask different questions from whether a speaker is extraterrestrial or whether a treatment works. No diagnosis of individual practitioners is made here.</p>${citations(['rt-survey','rt-content'])}</div></section><section class="method-grid"><h2>Take the research with you</h2><div><p>The research edition is dated October 22, 2026. Export the structured records to inspect sources, follow unresolved dates or extend the collection.</p><a class="button secondary" href="data.json" download="channeling-atlas-research.json">Download research data <span>↓</span></a></div></section>`}
function profileDetail(p){return `<span class="badge">${esc(p.entity)}</span><h2 id="dialog-title">${esc(p.name)}</h2><p>${esc(p.summary)}</p><dl class="record-facts"><div><dt>Human channeler / team</dt><dd>${esc(p.channeler)}</dd></div><div><dt>Attributed speaker / classification</dt><dd>${esc(p.entity)} · ${esc(p.classification)}</dd></div><div><dt>Claimed origin</dt><dd>${esc(p.origin||'Not established in the reviewed sources')}</dd></div><div><dt>First date in this profile</dt><dd>${date(p.firstDate)}${p.datePrecision?' · '+esc(p.datePrecision):''}</dd></div></dl><div class="source-note"><h4>What the date means</h4><p>${esc(p.dateBasis||'No reliable first date established in the reviewed record.')}</p></div>${arr(p.themes).length?`<section class="dialog-section"><h4>Recurring themes</h4>${tags(p.themes)}</section>`:''}${arr(p.claims).length?`<section class="dialog-section"><h4>Claims in the source material</h4>${ul(p.claims)}</section>`:''}${arr(p.caveats).length?`<section class="dialog-section"><h4>Context & unresolved questions</h4>${ul(p.caveats)}</section>`:''}${p.services?`<section class="dialog-section"><h4>Publicly described offerings</h4><p>${esc(p.services)}</p></section>`:''}${p.channelUrl?`<section class="dialog-section"><a class="text-link" href="${url(p.channelUrl)}" target="_blank" rel="noopener noreferrer">Public YouTube channel ↗</a></section>`:''}${youtubeProfileSummary(p)}<section class="dialog-section"><h4>Source trail</h4>${arr(p.sourceIds).map(id=>{const s=sourceMap.get(id);return s?`<div class="dialog-source"><a href="#/sources/${encodeURIComponent(id)}">[${String(s.index).padStart(2,'0')}] ${esc(s.title)} ↗</a><p>${esc(s.publisher)} · ${esc(s.kind)}</p></div>`:''}).join('')}</section>`}
function sourceDetail(s){return `<span class="badge">${esc(s.kind)}</span><h2 id="dialog-title">${esc(s.title)}</h2><dl class="record-facts"><div><dt>Publisher / source owner</dt><dd>${esc(s.publisher)}</dd></div><div><dt>Source date</dt><dd>${date(s.date)}</dd></div><div><dt>Reviewed for this edition</dt><dd>${date(s.accessed)}</dd></div><div><dt>Reference number</dt><dd>[${String(s.index).padStart(2,'0')}]</dd></div></dl>${s.notes?`<div class="source-note"><h4>Access & context</h4><p>${text(s.notes)}</p></div>`:''}<a class="button" href="${url(s.url)}" target="_blank" rel="noopener noreferrer">Open the original source <span>↗</span></a><section class="dialog-section"><h4>Referenced by</h4>${DATA.profiles.filter(p=>arr(p.sourceIds).includes(s.id)).map(p=>`<p style="margin-bottom:12px"><a href="#/profiles/${encodeURIComponent(p.id)}">${esc(p.name)} ↗</a></p>`).join('')||'<p>This source supports a timeline, media, community or research-method record.</p>'}</section>`}
const ytState={tab:'videos',search:'',profile:'',entity:'',relationship:'',format:'',date:'year'};
const sessionState={search:'',activity:'',access:''};
const ytData=()=>DATA.youtube&&typeof DATA.youtube==='object'&&!Array.isArray(DATA.youtube)?DATA.youtube:{accounts:[],videos:[],gaps:[],meta:{}};
const ytAccounts=()=>arr(ytData().accounts),ytVideos=()=>arr(ytData().videos);
const ytAccount=id=>ytAccounts().find(a=>a.id===id);
const ytProfiles=ids=>arr(ids).map(id=>profileMap.get(id)).filter(Boolean);
const profileNames=ids=>ytProfiles(ids).map(p=>p.channeler||p.name).join('; ');
const profileLinks=ids=>ytProfiles(ids).map(p=>`<a href="#/profiles/${encodeURIComponent(p.id)}">${esc(p.name)} ↗</a>`).join('');
const recentWindow=()=>({start:DATA.activity?.meta?.start||'2025-10-22',end:DATA.activity?.meta?.end||'2026-10-22'});
const knownUpload=v=>/^\d{4}-\d{2}-\d{2}$/.test(v.publishedAt||'');
const inYear=v=>knownUpload(v)&&v.publishedAt>=recentWindow().start&&v.publishedAt<=recentWindow().end;
const inMonth=v=>knownUpload(v)&&v.publishedAt>='2026-09-22'&&v.publishedAt<='2026-10-22';
const accountRel=a=>a?.relationship||'unresolved';
function coverageFor(profiles,vids,accounts){return profiles.map(p=>{const pv=vids.filter(v=>arr(v.profileIds).includes(p.id)),pa=accounts.filter(a=>arr(a.profileIds).includes(p.id)),known=pv.filter(knownUpload).map(v=>v.publishedAt).sort();return {profile:p,accounts:pa,videos:pv,count:new Set(pv.map(v=>v.id)).size,latest:known.at(-1)||null,unknown:pv.filter(v=>!knownUpload(v)).length,gaps:arr(ytData().gaps).filter(g=>g.profileId===p.id)}}).sort((a,b)=>b.count-a.count||a.profile.name.localeCompare(b.profile.name))}
function youtubeOverview(){const y=ytData(),accounts=ytAccounts(),vids=ytVideos(),covered=DATA.profiles.filter(p=>accounts.some(a=>arr(a.profileIds).includes(p.id))||vids.some(v=>arr(v.profileIds).includes(p.id))).length,rows=coverageFor(DATA.profiles,vids,accounts).filter(r=>r.count).slice(0,6),max=Math.max(1,...rows.map(r=>r.count));return `<section class="section youtube-overview"><div class="section-heading"><div><span class="eyebrow">THE VIDEO RESEARCH DESK</span><h2>Find the channel.<br>Follow the recording.</h2></div><p>Accounts, individual videos and claimed speakers in one source-linked index. Compare coverage, then open the original record.</p></div><div class="yt-overview-grid"><div><div class="yt-mini-stats"><div><b>${accounts.length}</b><span>account records</span></div><div><b>${vids.length}</b><span>distinct videos</span></div><div><b>${covered}/${DATA.profiles.length}</b><span>profiles with a media link</span></div></div><p class="yt-explainer">Official channels, institutional archives, interviews and community uploads carry separate labels. An unknown upload date remains unknown.</p><div class="hero-actions"><a class="button" href="#/youtube">Open YouTube index <span>↗</span></a><a class="text-link" href="#/sessions">Activity & sessions</a></div></div><div class="yt-mini-plot"><h4>Most indexed in this collection</h4>${rows.length?rows.map(r=>`<a href="#/youtube?profile=${encodeURIComponent(r.profile.id)}&date=all" class="yt-mini-row"><span>${esc(r.profile.channeler||r.profile.name)}</span><i style="--bar-width:${r.count/max*100}%"></i><b>${r.count}</b></a>`).join(''):'<p class="tiny">No indexed videos yet.</p>'}<p class="tiny">Curated coverage counts, not total output or popularity. <a href="#/youtube?tab=coverage">View the full plot ↗</a></p></div></div></section>`}
function ytSelect(id,label,options,value){return `<label class="yt-select"><span>${esc(label)}</span><select id="${id}" aria-label="${esc(label)}"><option value="">All</option>${options.map(x=>{const o=typeof x==='string'?{value:x,label:x}:x;return `<option value="${esc(o.value)}" ${value===o.value?'selected':''}>${esc(o.label)}</option>`}).join('')}</select></label>`}
function youtube(){const all=ytVideos(),accounts=ytAccounts(),entities=unique([...all.flatMap(v=>arr(v.entityLabels)),...accounts.flatMap(a=>arr(a.entityLabels))]);main.innerHTML=intro('THE YOUTUBE RESEARCH INDEX','Accounts. Videos. Claimed voices.','Explore the relationship between a human channeler, an attributed entity and the account that published a recording. This is a curated source index, not a complete YouTube census.')+`<aside class="reading-note discovery-callout"><p><strong>Explore the expanded collection.</strong> Find additional channelers, community publishers, playlists and repository records, with search provenance and CSV downloads.</p><a href="#/discovery">Expanded discovery ↗</a></aside><div class="yt-summary" aria-label="YouTube collection totals"><div><b>${accounts.length}</b><span>account records</span></div><div><b>${all.length}</b><span>distinct indexed videos</span></div><div><b>${all.filter(knownUpload).length}</b><span>exact upload dates established</span></div><div><b>${all.filter(v=>!knownUpload(v)).length}</b><span>upload dates unresolved</span></div></div><div class="yt-tabs" aria-label="YouTube index views">${[['videos','Individual videos'],['accounts','YouTube accounts'],['coverage','Coverage plot & table']].map(([id,label])=>`<button type="button" data-yt-tab="${id}" aria-pressed="${ytState.tab===id}">${label}</button>`).join('')}</div><div class="yt-filter-panel"><label class="search-wrap"><span class="sr-only">Search the YouTube index</span><input type="search" id="yt-search" aria-label="Search the YouTube index" placeholder="Search titles, people, entities, accounts…" value="${esc(ytState.search)}"></label><div class="yt-filter-grid">${ytSelect('yt-profile','Channeler / profile',DATA.profiles.map(p=>({value:p.id,label:p.name})),ytState.profile)}${ytSelect('yt-entity','Claimed entity',entities,ytState.entity)}${ytSelect('yt-relationship','Account relationship',unique(accounts.map(a=>accountRel(a))),ytState.relationship)}${ytSelect('yt-format','Video format',unique(all.map(v=>v.format)),ytState.format)}${ytSelect('yt-date','Upload date',[{value:'year',label:'Last year: Oct 22, 2025–Oct 22, 2026'},{value:'month',label:'Last month: Sep 22–Oct 22, 2026'},{value:'known',label:'Exact date established'},{value:'unknown',label:'Upload date unresolved'}],ytState.date)}</div><div class="yt-toolbar"><button type="button" class="yt-clear" data-yt-clear>Clear filters</button><span id="yt-count" role="status"></span><button type="button" class="yt-export" data-yt-export>Download current table CSV ↓</button></div></div><div id="yt-results"></div><aside class="reading-note"><p><strong>How to read the dates.</strong> Upload date can differ from recording date. The year filter uses only established upload dates; an undated record is not evidence of inactivity. Media access notes distinguish metadata, descriptions and transcripts.</p><a href="#/method">Research method ↗</a></aside><p class="yt-legacy-link"><a href="#/videos">Open the earlier mixed-media and recording-catalog trail ↗</a></p>`;refreshYoutube()}
function filteredYoutube(){const q=ytState.search.trim().toLowerCase(),allA=ytAccounts();const videos=ytVideos().filter(v=>{const a=ytAccount(v.accountId),hay=JSON.stringify([v,a?.title,profileNames(v.profileIds)]).toLowerCase();return (!q||hay.includes(q))&&(!ytState.profile||arr(v.profileIds).includes(ytState.profile))&&(!ytState.entity||arr(v.entityLabels).includes(ytState.entity))&&(!ytState.relationship||accountRel(a)===ytState.relationship)&&(!ytState.format||v.format===ytState.format)&&(!ytState.date||(ytState.date==='year'?inYear(v):ytState.date==='month'?inMonth(v):ytState.date==='known'?knownUpload(v):!knownUpload(v)))});const accounts=allA.filter(a=>{const hay=JSON.stringify([a,profileNames(a.profileIds)]).toLowerCase();return (!q||hay.includes(q)||videos.some(v=>v.accountId===a.id))&&(!ytState.profile||arr(a.profileIds).includes(ytState.profile))&&(!ytState.entity||arr(a.entityLabels).includes(ytState.entity)||videos.some(v=>v.accountId===a.id&&arr(v.entityLabels).includes(ytState.entity)))&&(!ytState.relationship||accountRel(a)===ytState.relationship)&&(!(ytState.date||ytState.format)||videos.some(v=>v.accountId===a.id))});const profiles=DATA.profiles.filter(p=>(!ytState.profile||p.id===ytState.profile)&&(!q||JSON.stringify(p).toLowerCase().includes(q)||videos.some(v=>arr(v.profileIds).includes(p.id))||accounts.some(a=>arr(a.profileIds).includes(p.id)))&&(!ytState.entity||videos.some(v=>arr(v.profileIds).includes(p.id))||accounts.some(a=>arr(a.profileIds).includes(p.id))));return {videos,accounts,coverage:coverageFor(profiles,videos,accounts)}}
function refreshYoutube(){const target=document.querySelector('#yt-results');if(!target)return;const data=filteredYoutube(),tab=ytState.tab;document.querySelectorAll('[data-yt-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.ytTab===tab)));document.querySelector('#yt-count').textContent=tab==='videos'?`${data.videos.length} of ${ytVideos().length} videos`:tab==='accounts'?`${data.accounts.length} of ${ytAccounts().length} accounts`:`${data.coverage.length} of ${DATA.profiles.length} profiles`;target.innerHTML=tab==='accounts'?youtubeAccountsTable(data.accounts):tab==='coverage'?youtubeCoverageView(data.coverage):youtubeVideoTable(data.videos)}
function ytRelationship(a){const r=accountRel(a);return `<span class="yt-relationship ${r==='official'||r==='organization/archive'?'verified':'other'}">${esc(r)}</span>`}
function youtubeVideoTable(rows){if(!rows.length)return empty('No indexed videos meet these filters. Try clearing the date filter to include records with unresolved upload dates.');return `<div class="yt-table-scroll" tabindex="0" aria-label="Scrollable individual video table"><table class="yt-table"><caption>Individual YouTube records in the current selection</caption><thead><tr><th scope="col">Recording & access</th><th scope="col">Channeler / claimed entity</th><th scope="col">Uploader / relationship</th><th scope="col">Upload date</th><th scope="col">Watch</th></tr></thead><tbody>${rows.map(v=>{const a=ytAccount(v.accountId);return `<tr><th scope="row"><a class="yt-record-title" href="#/youtube/video/${encodeURIComponent(v.id)}">${esc(v.title)}</a><span class="badge">${esc(v.format||'unresolved')}</span><p>${esc(v.contentBasis||'See source access note')}</p><a class="yt-detail-link" href="#/youtube/video/${encodeURIComponent(v.id)}">Evidence & details ↗</a></th><td><div class="yt-profile-links">${profileLinks(v.profileIds)}</div>${tags(v.entityLabels)}</td><td>${a?`<a href="#/youtube/account/${encodeURIComponent(a.id)}">${esc(a.title)}</a>${ytRelationship(a)}`:'<span class="yt-unresolved">Uploader not established</span>'}</td><td><span class="yt-upload">${date(v.publishedAt)}</span><p>${esc(v.dateBasis||'Exact upload date not established')}</p></td><td><a class="yt-watch" href="${url(v.url)}" target="_blank" rel="noopener noreferrer" aria-label="Watch ${esc(v.title)} on YouTube">YouTube ↗</a></td></tr>`}).join('')}</tbody></table></div>`}
function youtubeAccountsTable(rows){if(!rows.length)return empty('No account records meet these filters. An unresolved account relationship does not establish inactivity.');return `<div class="yt-table-scroll" tabindex="0" aria-label="Scrollable YouTube account table"><table class="yt-table"><caption>YouTube accounts and their source-supported relationships</caption><thead><tr><th scope="col">Account</th><th scope="col">Related people / traditions</th><th scope="col">Claimed entities</th><th scope="col">Verification & indexed videos</th></tr></thead><tbody>${rows.map(a=>`<tr><th scope="row"><a class="yt-record-title" href="#/youtube/account/${encodeURIComponent(a.id)}">${esc(a.title)}</a>${ytRelationship(a)}<a class="yt-detail-link" href="${url(a.url)}" target="_blank" rel="noopener noreferrer">Open account ↗</a></th><td><div class="yt-profile-links">${profileLinks(a.profileIds)}</div></td><td>${tags(a.entityLabels)}</td><td><p>${esc(a.verification||'Attribution unresolved; follow the source note.')}</p><span class="yt-table-count">${ytVideos().filter(v=>v.accountId===a.id).length} indexed videos</span>${citations(a.sourceIds)}</td></tr>`).join('')}</tbody></table></div>`}
function coverageSvg(rows,{compact=false}={}){const width=1000,left=330,right=70,top=55,rowHeight=34,height=top+rows.length*rowHeight+55,max=Math.max(1,...rows.map(r=>r.count)),plotWidth=width-left-right,ticks=[...new Set([0,Math.ceil(max/2),max])];return `<svg xmlns="http://www.w3.org/2000/svg" class="yt-coverage-svg" viewBox="0 0 ${width} ${height}" role="group" aria-label="Indexed videos by channeler. Curated coverage counts, not total YouTube output or popularity." style="font-family:Arial,Helvetica,sans-serif"><title>Indexed videos by channeler</title><desc>Each bar counts distinct indexed YouTube video records linked to a profile. A video may be linked to more than one profile. Select a row to filter the video index.</desc><rect width="${width}" height="${height}" fill="#fffef9"/><text x="20" y="25" font-size="15" fill="#202c28">Indexed videos by channeler</text>${ticks.map(t=>`<line x1="${left+t/max*plotWidth}" x2="${left+t/max*plotWidth}" y1="${top-10}" y2="${height-43}" stroke="#d3d8cd" stroke-width="1"/><text x="${left+t/max*plotWidth}" y="${height-20}" text-anchor="middle" font-size="12" fill="#626e65">${t}</text>`).join('')}${rows.map((r,i)=>{const y=top+i*rowHeight,label=r.profile.channeler||r.profile.name,short=label.length>43?label.slice(0,40)+'…':label;return `<g tabindex="0" role="button" class="yt-chart-row" data-yt-profile="${esc(r.profile.id)}" aria-label="${esc(label)}: ${r.count} indexed videos. Show this profile."><title>${esc(label)}: ${r.count} indexed videos</title><rect x="10" y="${y-3}" width="${width-20}" height="${rowHeight-3}" fill="transparent"/><text x="${left-16}" y="${y+17}" text-anchor="end" font-size="13" fill="#202c28">${esc(short)}</text>${r.count?`<rect x="${left}" y="${y+2}" width="${r.count/max*plotWidth}" height="20" fill="#405c49"/>`:`<line x1="${left}" x2="${left+5}" y1="${y+12}" y2="${y+12}" stroke="#bb4d2d" stroke-width="2"/>`}<text x="${left+r.count/max*plotWidth+9}" y="${y+17}" font-size="13" fill="#202c28">${r.count}</text></g>`}).join('')}<text x="${left+plotWidth/2}" y="${height-2}" text-anchor="middle" font-size="11" fill="#626e65">Distinct indexed video records</text></svg>`}
function youtubeCoverageView(rows){if(!rows.length)return empty();return `<section class="yt-chart-panel"><div class="section-heading"><div><span class="eyebrow">A PLOT OF THE INDEX</span><h2>How the collection is covered.</h2></div></div><p class="yt-chart-note">Coverage of this collection, not total YouTube output or popularity. Counts follow the current filters. Select a row to open that profile’s indexed videos.</p><div class="yt-chart-scroll" tabindex="0" aria-label="Scrollable coverage chart">${coverageSvg(rows)}</div><p class="tiny">A video can appear under several profiles, so profile counts should not be added to obtain the distinct-video total. Zero means no video is indexed here, not that a channeler is inactive.</p></section><div class="yt-table-scroll" tabindex="0" aria-label="Scrollable profile coverage table"><table class="yt-table yt-coverage-table"><caption>Channeler-to-account and entity mapping</caption><thead><tr><th scope="col">Channeler / profile</th><th scope="col">Claimed entity</th><th scope="col">Linked accounts</th><th scope="col">Videos</th><th scope="col">Latest known upload</th><th scope="col">Coverage gaps</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row"><a href="#/profiles/${encodeURIComponent(r.profile.id)}">${esc(r.profile.name)}</a></th><td>${esc(r.profile.entity)}</td><td>${r.accounts.length?r.accounts.map(a=>`<a class="yt-account-inline" href="#/youtube/account/${encodeURIComponent(a.id)}">${esc(a.title)}</a>${ytRelationship(a)}`).join(''):'<span class="yt-unresolved">No account securely linked</span>'}</td><td><button type="button" class="yt-count-button" data-yt-profile="${esc(r.profile.id)}">${r.count}</button><p>${r.unknown} unresolved upload dates</p></td><td>${date(r.latest)}</td><td>${r.gaps.length?r.gaps.map(g=>`<p>${esc(g.reason)}</p>`).join(''):r.count?'Curated sample; not an exhaustive account inventory.':'No individual video securely indexed.'}</td></tr>`).join('')}</tbody></table></div>`}
function youtubeProfileSummary(p){const a=ytAccounts().filter(a=>arr(a.profileIds).includes(p.id)),v=ytVideos().filter(v=>arr(v.profileIds).includes(p.id));return `<section class="dialog-section"><h4>YouTube account & video index</h4><p>${a.length} linked account records · ${v.length} indexed individual videos.</p>${a.slice(0,4).map(x=>`<div class="dialog-source"><a href="#/youtube/account/${encodeURIComponent(x.id)}">${esc(x.title)} ↗</a><p>${esc(x.relationship)} · ${esc(x.verification)}</p></div>`).join('')}${v.slice(0,3).map(x=>`<div class="dialog-source"><a href="#/youtube/video/${encodeURIComponent(x.id)}">${esc(x.title)} ↗</a><p>${esc(x.format)} · ${date(x.publishedAt)}</p></div>`).join('')}<p style="margin-top:17px"><a class="text-link" href="#/youtube?profile=${encodeURIComponent(p.id)}&date=all">Open all media for this profile ↗</a></p></section>`}
function youtubeDetail(record,kind){const account=kind==='account'?record:ytAccount(record.accountId),vids=kind==='account'?ytVideos().filter(v=>v.accountId===record.id):[];return `<span class="badge">YOUTUBE ${kind==='account'?'ACCOUNT':'VIDEO'} RECORD</span><h2 id="dialog-title">${esc(record.title)}</h2><dl class="record-facts"><div><dt>${kind==='account'?'Account relationship':'Video format'}</dt><dd>${esc(kind==='account'?record.relationship:record.format)}</dd></div><div><dt>${kind==='account'?'Indexed videos':'Uploader / account'}</dt><dd>${kind==='account'?vids.length:account?esc(account.title):'Not established'}</dd></div>${kind==='video'?`<div><dt>Upload date</dt><dd>${date(record.publishedAt)}</dd></div>`:''}<div><dt>Claimed entities</dt><dd>${arr(record.entityLabels).map(esc).join('; ')||'Not assigned'}</dd></div></dl><div class="source-note"><h4>${kind==='account'?'Attribution basis':'Access & date basis'}</h4><p>${esc(kind==='account'?record.verification:record.contentBasis)}</p>${kind==='video'?`<p>${esc(record.dateBasis)}</p>`:''}</div>${record.notes?`<p>${esc(record.notes)}</p>`:''}<a class="button" style="margin-top:20px" href="${url(record.url)}" target="_blank" rel="noopener noreferrer">${kind==='account'?'Open YouTube account':'Watch on YouTube'} <span>↗</span></a><section class="dialog-section"><h4>Related people & traditions</h4><div class="entity-links">${profileLinks(record.profileIds)}</div></section>${kind==='account'&&vids.length?`<section class="dialog-section"><h4>Indexed videos on this account</h4>${vids.map(v=>`<div class="dialog-source"><a href="#/youtube/video/${encodeURIComponent(v.id)}">${esc(v.title)} ↗</a><p>${esc(v.format)} · ${date(v.publishedAt)}</p></div>`).join('')}</section>`:''}<section class="dialog-section"><h4>Source trail</h4>${citations(record.sourceIds)}</section>`}
function triggerDownload(name,body,mime){const blob=new Blob([body],{type:mime}),href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000)}
function csvCell(value){const raw=Array.isArray(value)?value.join('; '):String(value??''),safe=/^[=+\-@]/.test(raw)?"'"+raw:raw;return '"'+safe.replace(/"/g,'""')+'"'}
function csvBody(headers,rows){return '\ufeff'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n'}
function exportYoutube(){const d=filteredYoutube(),t=ytState.tab;let headers,rows;if(t==='accounts'){headers=['Account','URL','Relationship','Profiles','Claimed entities','Verification','Indexed videos'];rows=d.accounts.map(a=>[a.title,a.url,a.relationship,profileNames(a.profileIds),arr(a.entityLabels),a.verification,ytVideos().filter(v=>v.accountId===a.id).length])}else if(t==='coverage'){headers=['Profile','Claimed entity','Accounts','Indexed videos','Latest known upload','Unresolved upload dates','Gaps'];rows=d.coverage.map(r=>[r.profile.name,r.profile.entity,r.accounts.map(a=>a.title),r.count,r.latest,r.unknown,r.gaps.map(g=>g.reason)])}else{headers=['Title','YouTube URL','Profiles','Claimed entities','Account','Account relationship','Video format','Upload date','Date basis','Content access basis','Notes'];rows=d.videos.map(v=>{const a=ytAccount(v.accountId);return[v.title,v.url,profileNames(v.profileIds),arr(v.entityLabels),a?.title||'',accountRel(a),v.format,v.publishedAt,v.dateBasis,v.contentBasis,v.notes]})}triggerDownload(`channeling-atlas-youtube-${t}.csv`,csvBody(headers,rows),'text/csv;charset=utf-8')}
function activityRows(){return arr(DATA.activity?.records)}
function contemporaryEtRows(){return activityRows().filter(r=>r.etAssociated&&r.status!=='historical')}
function activeCount(){return new Set(activityRows().filter(r=>r.etAssociated&&r.status==='confirmed').map(r=>r.profileId)).size}
function sessions(){const window=recentWindow(),confirmed=activeCount(),et=contemporaryEtRows(),all=arr(DATA.services);main.innerHTML=intro('YEARLY ACTIVITY & PUBLIC OFFERS','Activity, dates & session prices.','A dated view of public posting evidence and advertised services. Activity counts people with confirmed ET-associated material in the stated window; it does not count entities, accounts or historical archives as active people.')+`<div class="yt-summary"><div><b>${confirmed}</b><span>confirmed ET-associated practitioners</span></div><div><b>${new Set(et.map(r=>r.profileId)).size}</b><span>contemporary ET-associated candidates reviewed</span></div><div><b>${all.filter(s=>s.nextStatus==='confirmed public').length}</b><span>confirmed public session dates</span></div><div><b>${all.filter(s=>s.nextStatus==='confirmed private').length}</b><span>confirmed private opening dates</span></div></div><p class="yt-date-window"><strong>Activity window:</strong> ${date(window.start)}–${date(window.end)}. Unknown or unresolved posting evidence is not a finding of inactivity.</p>${DATA.activity?.meta?.scope?`<p class="yt-date-window">${text(DATA.activity.meta.scope)}</p>`:''}<div class="yt-filter-panel"><label class="search-wrap"><span class="sr-only">Search activity and sessions</span><input type="search" id="session-search" aria-label="Search activity and sessions" placeholder="Search people, entities, services…" value="${esc(sessionState.search)}"></label><div class="yt-filter-grid session-filter-grid">${ytSelect('session-activity','Activity status',unique(activityRows().map(r=>r.status)),sessionState.activity)}${ytSelect('session-access','Session access',[{value:'public',label:'Confirmed public date'},{value:'private',label:'Confirmed private opening'},{value:'free',label:'Free / donation-based options'},{value:'unpublished',label:'Date not securely published'}],sessionState.access)}</div><div class="yt-toolbar"><button type="button" class="yt-clear" data-session-clear>Clear filters</button><span id="session-count" role="status"></span><button type="button" class="yt-export" data-session-export>Download activity & services CSV ↓</button></div></div><div id="session-results"></div>`;refreshSessions()}
function hasFreeAccess(s){if(!s)return false;const free=String(s.freeLabel||'');return /donation-based/i.test(s.priceLabel||'')||(!/^(none|no\b|not\b|unverified|unpublished)/i.test(free)&&/free|donation/i.test(free));}
function filteredSessions(){const q=sessionState.search.trim().toLowerCase(),ids=unique([...activityRows().map(r=>r.profileId),...arr(DATA.services).map(r=>r.profileId)]);return ids.map(id=>({profile:profileMap.get(id),activity:activityRows().find(r=>r.profileId===id),service:arr(DATA.services).find(r=>r.profileId===id)})).filter(r=>r.profile).filter(r=>(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!sessionState.activity||r.activity?.status===sessionState.activity)&&(!sessionState.access||(sessionState.access==='public'?r.service?.nextStatus==='confirmed public':sessionState.access==='private'?r.service?.nextStatus==='confirmed private':sessionState.access==='free'?hasFreeAccess(r.service):!['confirmed public','confirmed private'].includes(r.service?.nextStatus))))}
function refreshSessions(){const rows=filteredSessions(),target=document.querySelector('#session-results');if(!target)return;document.querySelector('#session-count').textContent=`${rows.length} people / profiles in the current selection`;const statuses=unique(contemporaryEtRows().map(r=>r.status)),total=Math.max(1,...statuses.map(s=>new Set(contemporaryEtRows().filter(r=>r.status===s).map(r=>r.profileId)).size));target.innerHTML=`<section class="activity-plot" aria-label="Activity evidence status chart"><h4>ET-associated activity evidence in the yearly window</h4>${statuses.map(s=>{const n=new Set(contemporaryEtRows().filter(r=>r.status===s).map(r=>r.profileId)).size;return `<div class="activity-plot-row"><span>${esc(s)}</span><div><i style="width:${n/total*100}%"></i></div><b>${n}</b></div>`}).join('')}<p class="tiny">Counts refer to 14 contemporary candidates, not a worldwide population estimate. Historical and other traditions remain available in the evidence table below.</p></section>${rows.length?`<div class="yt-table-scroll" tabindex="0" aria-label="Scrollable activity and session services table"><table class="yt-table session-table"><caption>Yearly publication evidence, upcoming sessions and displayed prices</caption><thead><tr><th scope="col">Practitioner / claimed source</th><th scope="col">Yearly activity evidence</th><th scope="col">Next session / availability</th><th scope="col">Price, private services & free material</th><th scope="col">Sources / booking</th></tr></thead><tbody>${rows.map(r=>{const p=r.profile,a=r.activity,s=r.service;return `<tr><th scope="row"><a href="#/profiles/${encodeURIComponent(p.id)}">${esc(p.channeler||p.name)}</a><p>${esc(p.entity)}</p>${a?`<span class="yt-relationship ${a.status==='confirmed'&&a.etAssociated?'verified':'other'}">${esc(a.status)}</span><p class="tiny">${a.etAssociated?'ET-associated source':'Other tradition / historical context'}</p>`:''}</th><td>${a?`<strong>${date(a.publishedAt)}</strong><p>${esc(a.evidenceTitle||'No qualifying publication established')}</p><p>${esc(a.dateBasis||'')}</p>${a.evidenceType?`<p class="tiny"><b>Evidence type:</b> ${esc(a.evidenceType)}</p>`:''}${a.notes?`<p>${text(a.notes)}</p>`:''}${a.evidenceUrl?`<a class="yt-detail-link" href="${url(a.evidenceUrl)}" target="_blank" rel="noopener noreferrer">Open publication evidence ↗</a>`:''}`:'Activity not assessed in this edition.'}</td><td>${s?`<span class="badge">${esc(s.nextStatus)}</span><strong class="session-next-date">${s.nextDate?date(s.nextDate):'Date not securely published'}</strong>${s.nextDate&&s.nextTime?`<p>${esc(s.nextTime)} ${esc(s.timeZone||'')}</p>`:''}<p>${esc(s.sessionTitle||s.sessionType||'')}</p>${arr(s.notes).map(n=>`<p class="tiny">${text(n)}</p>`).join('')}`:'No session service audited for this profile.'}</td><td>${s?`<strong>${esc(s.priceLabel||'Price not published')}</strong>${s.privateLabel?`<p><b>Private:</b> ${esc(s.privateLabel)}</p>`:''}${s.freeLabel?`<p><b>Free / low-cost access:</b> ${esc(s.freeLabel)}</p>`:''}<p class="tiny">Checked ${date(s.checkedAt)}</p>`:'No service price established.'}</td><td>${s?.bookingUrl?`<a class="yt-watch" href="${url(s.bookingUrl)}" target="_blank" rel="noopener noreferrer">Official details / booking ↗</a>`:''}${citations([...new Set([...arr(a?.sourceIds),...arr(s?.sourceIds)])])}</td></tr>`}).join('')}</tbody></table></div>`:empty()}`}
function exportSessions(){const rows=filteredSessions().map(({profile:p,activity:a,service:s})=>[p.channeler||p.name,p.entity,a?.etAssociated,a?.status,a?.publishedAt,a?.datePrecision,a?.dateBasis,a?.evidenceType,a?.evidenceTitle,a?.evidenceUrl,s?.nextStatus,s?.nextDate,s?.nextTime,s?.timeZone,s?.sessionTitle,s?.priceLabel,s?.privateLabel,s?.freeLabel,s?.bookingUrl,arr(s?.notes),s?.checkedAt]);triggerDownload('channeling-atlas-activity-and-sessions.csv',csvBody(['Practitioner','Claimed entity','ET associated','Activity status','Publication date','Date precision','Date basis','Evidence type','Publication evidence','Evidence URL','Next session status','Next date','Next time','Time zone','Session','Displayed price','Private services','Free access','Booking URL','Notes','Checked date'],rows),'text/csv;charset=utf-8')}
main.addEventListener('input',e=>{if(e.target.id==='yt-search'){ytState.search=e.target.value;refreshYoutube()}if(e.target.id==='session-search'){sessionState.search=e.target.value;refreshSessions()}});
main.addEventListener('change',e=>{if(e.target.id.startsWith('yt-')){const key=e.target.id.slice(3);if(key in ytState){ytState[key]=e.target.value;refreshYoutube()}}if(e.target.id==='session-activity'){sessionState.activity=e.target.value;refreshSessions()}if(e.target.id==='session-access'){sessionState.access=e.target.value;refreshSessions()}});
main.addEventListener('click',e=>{const tab=e.target.closest('[data-yt-tab]'),profile=e.target.closest('[data-yt-profile]');if(tab){ytState.tab=tab.dataset.ytTab;refreshYoutube()}if(profile){ytState.profile=profile.dataset.ytProfile;ytState.tab='videos';youtube();document.querySelector('#yt-results')?.scrollIntoView({block:'start',behavior:'instant'})}if(e.target.closest('[data-yt-clear]')){Object.assign(ytState,{search:'',profile:'',entity:'',relationship:'',format:'',date:''});youtube()}if(e.target.closest('[data-yt-export]'))exportYoutube();if(e.target.closest('[data-session-clear]')){Object.assign(sessionState,{search:'',activity:'',access:''});sessions()}if(e.target.closest('[data-session-export]'))exportSessions()});
main.addEventListener('keydown',e=>{const profile=e.target.closest('.yt-chart-row[data-yt-profile]');if(profile&&(e.key==='Enter'||e.key===' ')){e.preventDefault();profile.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});

/* Expanded discovery keeps repository imports and fresh searches inspectable. */
const discoveryState={tab:'all',search:'',person:'',entity:'',relationship:'',depth:'',page:1};
const discoveryKinds={account:'Accounts',playlist:'Playlists',video:'Videos',website:'Websites'};
function discoveryData(){return DATA.discovery||{meta:{},people:[],records:[],queries:[],gaps:[]}}
function discoveryRows(){return arr(discoveryData().records)}
function discoveryPeople(){return arr(discoveryData().people)}
function discoveryAccess(value){return ({repository_metadata:'Inherited repository metadata',search_metadata:'Search-result metadata',page_metadata:'Page metadata',page_text:'Page text inspected',browser_metadata:'Browser metadata inspected'})[value]||value||'Access depth unresolved'}
function discoveryLinks(urls){return unique(arr(urls)).map(link=>{let label=link;try{const u=new URL(link);label=u.hostname.replace(/^www\./,'')+u.pathname.slice(0,60)}catch{}return `<a href="${url(link)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`}).join('')}
function discoveryOverview(){const rows=discoveryRows();return `<section class="section discovery-overview"><div><span class="eyebrow">BEYOND THE FIRST SAMPLE</span><h2>The wider channeling trail.</h2><p>Search by human, claimed civilization or publisher. The expanded collection brings together repository records, manually inspected YouTube results, smaller websites and playlists.</p><a class="button" href="#/discovery">Expanded discovery <span>↗</span></a></div><div class="discovery-overview-counts"><div><b>${rows.length}</b><span>linked records</span></div><div><b>${rows.filter(r=>r.kind==='account').length}</b><span>account links</span></div><div><b>${rows.filter(r=>r.kind==='playlist').length}</b><span>playlist links</span></div><div><b>${discoveryPeople().length}</b><span>people / attributed practices</span></div></div><p class="tiny">Collection counts describe indexed links. Repost publishers are separate from channelers; these totals are not an active-medium census.</p></section>`}
function discovery(){const d=discoveryData(),rows=discoveryRows(),people=unique([...discoveryPeople().map(p=>p.name),...rows.flatMap(r=>arr(r.personNames))]),entities=unique(rows.flatMap(r=>[...arr(r.entityLabels),...arr(r.civilizations)]));main.innerHTML=intro('EXPANDED SEARCH · ACCOUNTS · PLAYLISTS','Follow the wider trail.','A broader index of channelers, attributed entities and the accounts that publish them. Reposts, archives, interviews and original sources retain separate labels.')+`<div class="yt-summary" aria-label="Expanded discovery totals"><div><b>${rows.length}</b><span>unique linked records</span></div><div><b>${rows.filter(r=>r.kind==='account').length}</b><span>account links</span></div><div><b>${rows.filter(r=>r.kind==='playlist').length}</b><span>playlist links</span></div><div><b>${rows.filter(r=>r.kind==='video').length}</b><span>individual videos</span></div></div><p class="yt-date-window"><strong>Expansion checked:</strong> ${date(d.meta?.checkedAt)}. ${esc(d.meta?.scope||'All years are included. Exact dates remain unknown when the inspected source does not establish them.')}</p><div class="discovery-downloads"><a href="exports/channeling-research-csv.zip" download>Download complete CSV bundle ↓</a><span>Full tables:</span>${[['channeling-links.csv','All links'],['accounts.csv','Accounts'],['playlists.csv','Playlists'],['videos.csv','Videos'],['people.csv','People'],['search-log.csv','Search log']].map(([file,label])=>`<a href="exports/${file}" download>${label} CSV ↓</a>`).join('')}</div><div class="yt-tabs discovery-tabs" aria-label="Expanded discovery views">${[['all','All links'],['account','Accounts'],['playlist','Playlists'],['video','Videos'],['people','People'],['queries','Search log']].map(([id,label])=>`<button type="button" data-discovery-tab="${id}" aria-pressed="${discoveryState.tab===id}">${label}</button>`).join('')}</div><div class="yt-filter-panel"><label class="search-wrap"><span class="sr-only">Search expanded discovery</span><input type="search" id="discovery-search" aria-label="Search expanded discovery" placeholder="Search titles, channelers, civilizations, publishers…" value="${esc(discoveryState.search)}"></label><div class="yt-filter-grid discovery-filter-grid">${ytSelect('discovery-person','Human / attributed practice',people,discoveryState.person)}${ytSelect('discovery-entity','Entity / civilization',entities,discoveryState.entity)}${ytSelect('discovery-relationship','Publisher relationship',unique(rows.map(r=>r.relationship)),discoveryState.relationship)}${ytSelect('discovery-depth','Inspection depth',unique(rows.map(r=>r.accessDepth)).map(v=>({value:v,label:discoveryAccess(v)})),discoveryState.depth)}</div><div class="yt-toolbar"><button type="button" class="yt-clear" data-discovery-clear>Clear discovery filters</button><span id="discovery-count" role="status"></span><button type="button" class="yt-export" data-discovery-export>Download filtered CSV ↓</button></div><p class="tiny discovery-filter-note">The Search log view uses the search text only. Other filters apply to linked records and the People view.</p></div><div id="discovery-results"></div><details class="discovery-limits"><summary>Search coverage, repository provenance & unresolved gaps</summary><p class="tiny">A discovered link is not a full-content review. A YouTube upload can present an old session; a title or narrator alone does not establish the human speaker.</p>${d.meta?.repoCommit?`<p class="tiny"><b>Repository snapshot:</b> <code>${esc(d.meta.repoCommit)}</code></p>`:''}${ul([...arr(d.meta?.limitations),...arr(d.gaps)])}</details>`;refreshDiscovery()}
function discoveryFilteredRecords(){const s=discoveryState,q=s.search.trim().toLowerCase();return discoveryRows().filter(r=>(!q||JSON.stringify(r).toLowerCase().includes(q))&&(!s.person||arr(r.personNames).includes(s.person))&&(!s.entity||[...arr(r.entityLabels),...arr(r.civilizations)].includes(s.entity))&&(!s.relationship||r.relationship===s.relationship)&&(!s.depth||r.accessDepth===s.depth)&&(!['account','playlist','video'].includes(s.tab)||r.kind===s.tab)).sort((a,b)=>String(a.title||'').localeCompare(String(b.title||'')))}
function discoveryFilteredPeople(rows){const s=discoveryState,q=s.search.trim().toLowerCase();return discoveryPeople().filter(p=>{const linked=rows.filter(r=>arr(r.personNames).includes(p.name)||arr(p.recordIds).includes(r.id));return (!s.person||p.name===s.person)&&(!s.entity||[...arr(p.entities),...arr(p.civilizations)].includes(s.entity)||linked.length)&&(!(s.relationship||s.depth)||linked.length)&&(!q||JSON.stringify(p).toLowerCase().includes(q)||linked.length)}).sort((a,b)=>String(a.name).localeCompare(String(b.name)))}
function discoveryFilteredQueries(){const q=discoveryState.search.trim().toLowerCase();return arr(discoveryData().queries).filter(r=>!q||JSON.stringify(r).toLowerCase().includes(q))}
function discoveryPlot(rows){const counts=Object.entries(discoveryKinds).map(([kind,label])=>({kind,label,n:rows.filter(r=>r.kind===kind).length})),max=Math.max(1,...counts.map(r=>r.n));return `<section class="activity-plot discovery-plot" aria-label="Linked records by kind"><h4>What is indexed in this selection</h4>${counts.map(r=>`<div class="activity-plot-row"><span>${r.label}</span><div><i style="width:${r.n/max*100}%"></i></div><b>${r.n}</b></div>`).join('')}<p class="tiny">Each bar counts unique indexed URLs by type. These are collection-coverage counts, not popularity, authenticity or the total output of a channeler.</p></section>`}
function discoveryPager(total){const pages=Math.max(1,Math.ceil(total/50));return pages>1?`<div class="discovery-pager"><button type="button" data-discovery-page="${discoveryState.page-1}" ${discoveryState.page<=1?'disabled':''}>← Previous</button><span>Page ${discoveryState.page} of ${pages} · 50 per page</span><button type="button" data-discovery-page="${discoveryState.page+1}" ${discoveryState.page>=pages?'disabled':''}>Next →</button></div>`:''}
function discoveryRecordTable(rows){return `<div class="yt-table-scroll" tabindex="0" aria-label="Scrollable expanded discovery table"><table class="yt-table discovery-table"><caption>Source-linked accounts, playlists, videos and websites</caption><thead><tr><th scope="col">Record / type</th><th scope="col">Human / claimed entity</th><th scope="col">Publisher relationship</th><th scope="col">Date / inspection depth</th><th scope="col">Provenance & content notes</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row"><a class="yt-record-title" href="${url(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title||r.url)} ↗</a><span class="badge">${esc(r.kind)}</span><a class="discovery-url" href="${url(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.url)}</a></th><td>${arr(r.personNames).map(p=>`<button type="button" class="discovery-person-button" data-discovery-person="${esc(p)}">${esc(p)}</button>`).join('')||'<span class="yt-unresolved">Human not established</span>'}${tags([...arr(r.entityLabels),...arr(r.civilizations)])}</td><td><strong>${esc(r.publisher||'Publisher not established')}</strong><span class="yt-relationship ${['official','organization/archive'].includes(r.relationship)?'verified':'other'}">${esc(r.relationship||'unresolved')}</span>${r.accountUrl?`<a href="${url(r.accountUrl)}" target="_blank" rel="noopener noreferrer">Publisher account ↗</a>`:''}</td><td><span class="yt-upload">${date(r.publishedAt)}</span><p>${esc(r.dateBasis||'Exact publication date not established.')}</p><span class="discovery-access ${r.accessDepth==='repository_metadata'?'inherited':''}">${esc(discoveryAccess(r.accessDepth))}</span></td><td><details><summary>Read source trail & notes</summary>${r.notes?`<p>${esc(r.notes)}</p>`:''}${r.discoveryQuery?`<p><b>Discovery:</b> ${esc(r.discoveryQuery)}</p>`:''}${arr(r.workstreams).length?`<p><b>Workstreams:</b> ${arr(r.workstreams).map(esc).join('; ')}</p>`:''}<div class="discovery-source-links">${discoveryLinks(r.sourceUrls)||'<span class="yt-unresolved">Supporting source URL unresolved</span>'}</div></details></td></tr>`).join('')}</tbody></table></div>`}
function discoveryPeopleView(people,records){return `<p class="yt-date-window">These ${people.length} named people / attributed practices group the discovered links. This view includes past material and unresolved leads; it does not establish how many mediums are currently active.</p><div class="discovery-people">${people.map(p=>{const linked=records.filter(r=>arr(r.personNames).includes(p.name)||arr(p.recordIds).includes(r.id));return `<article class="discovery-person-card"><h3>${esc(p.name)}</h3>${tags([...arr(p.entities),...arr(p.civilizations)])}${p.website?`<a class="text-link" href="${url(p.website)}" target="_blank" rel="noopener noreferrer">Practitioner website ↗</a>`:''}${p.notes?`<p>${esc(p.notes)}</p>`:''}${p.csvPath&&/^exports\/by-channeler\/[a-z0-9-]+\.csv$/.test(p.csvPath)?`<a class="text-link" href="${esc(p.csvPath)}" download>Download this practitioner’s links CSV ↓</a>`:''}<div class="discovery-person-totals">${Object.entries(discoveryKinds).map(([kind,label])=>`${linked.filter(r=>r.kind===kind).length} ${label.toLowerCase()}`).join(' · ')}</div>${linked.length?`<details><summary>Browse ${linked.length} matching links</summary><ul>${linked.map(r=>`<li><span>${esc(r.kind)}</span> <a href="${url(r.url)}" target="_blank" rel="noopener noreferrer">${esc(r.title||r.url)} ↗</a><small>${esc(r.relationship||'unresolved')} · ${esc(discoveryAccess(r.accessDepth))}</small></li>`).join('')}</ul></details>`:'<p class="tiny">No linked records meet the current filters. Review the source trail for this lead.</p>'}<details class="discovery-person-sources"><summary>Person attribution sources</summary><div class="discovery-source-links">${discoveryLinks(p.sourceUrls)}</div></details></article>`}).join('')}</div>`}
function discoveryQueryTable(rows){return `<div class="yt-table-scroll" tabindex="0" aria-label="Scrollable discovery search log"><table class="yt-table discovery-query-table"><caption>Executed discovery queries and repository search seeds</caption><thead><tr><th scope="col">Query / search seed</th><th scope="col">Method</th><th scope="col">Checked</th><th scope="col">Result / limitation</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.query||'Repository seed')}${r.url?`<a class="discovery-url" href="${url(r.url)}" target="_blank" rel="noopener noreferrer">Open search / seed ↗</a>`:''}</th><td>${esc(r.method||'Not recorded')}</td><td>${date(r.checkedAt)}</td><td>${esc(r.notes||'See the linked records for retrieved material and attribution.')}</td></tr>`).join('')}</tbody></table></div>`}
function refreshDiscovery(){const target=document.querySelector('#discovery-results');if(!target)return;const rows=discoveryFilteredRecords(),tab=discoveryState.tab,people=tab==='people'?discoveryFilteredPeople(rows):[],queries=tab==='queries'?discoveryFilteredQueries():[],items=tab==='people'?people:tab==='queries'?queries:rows,total=items.length;discoveryState.page=Math.max(1,Math.min(discoveryState.page,Math.max(1,Math.ceil(total/50))));const from=(discoveryState.page-1)*50,page=items.slice(from,from+50);document.querySelectorAll('[data-discovery-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.discoveryTab===tab)));document.querySelector('#discovery-count').textContent=`${total?from+1:0}–${Math.min(from+50,total)} of ${total} ${tab==='people'?'people / practices':tab==='queries'?'search entries':'matching links'}`;target.innerHTML=(tab==='people'||tab==='queries'?'':discoveryPlot(rows))+(total?(tab==='people'?discoveryPeopleView(page,rows):tab==='queries'?discoveryQueryTable(page):discoveryRecordTable(page)):empty('No matching discovery records. Clear the filters to explore the full collection.'))+discoveryPager(total)}
function exportDiscovery(){const tab=discoveryState.tab;let headers,rows;if(tab==='queries'){headers=['Query / seed','Method','URL','Checked date','Notes'];rows=discoveryFilteredQueries().map(q=>[q.query,q.method,q.url,q.checkedAt,q.notes])}else if(tab==='people'){headers=['Name','Claimed entities','Civilizations','Website','Notes','Source URLs','Matching record URLs'];const records=discoveryFilteredRecords();rows=discoveryFilteredPeople(records).map(p=>[p.name,arr(p.entities),arr(p.civilizations),p.website,p.notes,arr(p.sourceUrls),records.filter(r=>arr(r.personNames).includes(p.name)||arr(p.recordIds).includes(r.id)).map(r=>r.url)])}else{headers=['Kind','Title','URL','Human / attributed practice','Claimed entities','Civilizations','Publisher','Account URL','Relationship','Publication date','Date basis','Access depth','Discovery query','Source URLs','Notes','Workstreams'];rows=discoveryFilteredRecords().map(r=>[r.kind,r.title,r.url,arr(r.personNames),arr(r.entityLabels),arr(r.civilizations),r.publisher,r.accountUrl,r.relationship,r.publishedAt,r.dateBasis,r.accessDepth,r.discoveryQuery,arr(r.sourceUrls),r.notes,arr(r.workstreams)])}triggerDownload(`channeling-atlas-discovery-${tab}.csv`,csvBody(headers,rows),'text/csv;charset=utf-8')}
main.addEventListener('input',e=>{if(e.target.id==='discovery-search'){discoveryState.search=e.target.value;discoveryState.page=1;refreshDiscovery()}});
main.addEventListener('change',e=>{if(e.target.id.startsWith('discovery-')){const key=e.target.id.slice(10);if(key in discoveryState){discoveryState[key]=e.target.value;discoveryState.page=1;refreshDiscovery()}}});
main.addEventListener('click',e=>{const tab=e.target.closest('[data-discovery-tab]'),person=e.target.closest('[data-discovery-person]'),page=e.target.closest('[data-discovery-page]');if(tab){discoveryState.tab=tab.dataset.discoveryTab;discoveryState.page=1;refreshDiscovery()}if(person){discoveryState.person=person.dataset.discoveryPerson;discoveryState.tab='all';discoveryState.page=1;discovery();document.querySelector('#discovery-results')?.scrollIntoView({block:'start',behavior:'instant'})}if(page&&!page.disabled){discoveryState.page=Number(page.dataset.discoveryPage);refreshDiscovery();document.querySelector('#discovery-results')?.scrollIntoView({block:'start',behavior:'instant'})}if(e.target.closest('[data-discovery-clear]')){Object.assign(discoveryState,{search:'',person:'',entity:'',relationship:'',depth:'',page:1});discovery()}if(e.target.closest('[data-discovery-export]'))exportDiscovery()});

/* Reproducible sample analysis; fetched separately from the discovery catalogue. */
let ANALYSIS=null, analysisRequest=null;
const analysisState={tab:'channels',search:'',sort:'duration-desc',coverage:'all',channel:'',compare:'',page:1};
const analysisTabs=[['channels','Channel table'],['channel','Channel detail'],['compare','Topic comparisons'],['method','Methods & downloads']];
function analysisNumber(v,d=1){return typeof v==='number'&&Number.isFinite(v)?v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—'}
function analysisPercent(v){return typeof v==='number'&&Number.isFinite(v)?Math.round(v*100)+'%':'—'}
function analysisSafePath(v){return typeof v==='string'&&/^(?:analysis\/)?[a-zA-Z0-9_./-]+\.(?:svg|png|csv|json|html|md|zip)$/.test(v)&&!v.includes('..')?(v.startsWith('analysis/')?v:'analysis/'+v):''}
function analysisChannels(){return arr(ANALYSIS?.channels)}
function analysisChannel(id){return analysisChannels().find(c=>c.id===id)}
function analysisLabel(id){return analysisChannel(id)?.name||id}
function analysisOptions(selected,exclude=''){return analysisChannels().map(c=>`<option value="${esc(c.id)}" ${c.id===selected?'selected':''} ${c.id===exclude?'disabled':''}>${esc(c.name)} (${Number(c.videoCount)||0} videos)</option>`).join('')}
function analysis(){
 if(!ANALYSIS){main.innerHTML=intro('COMPARATIVE RESEARCH','Loading the analysis.','Opening the channel samples, duration measurements and text comparisons…')+'<p role="status">Loading analysis data.</p>';if(!analysisRequest)analysisRequest=fetch('analysis/data.json').then(r=>{if(!r.ok)throw Error('The analysis data could not be loaded.');return r.json()}).then(d=>{ANALYSIS=d;if(currentView==='analysis')analysis()}).catch(e=>{analysisRequest=null;if(currentView==='analysis')main.innerHTML=intro('ANALYSIS UNAVAILABLE','The analysis could not open.',esc(e.message))+'<button class="button" data-analysis-retry>Try again</button> <a class="text-link" href="analysis/data.json">Open the data file ↗</a>'});return;}
 if(!analysisChannel(analysisState.channel))analysisState.channel=analysisChannels().find(c=>c.durationCount>1)?.id||analysisChannels()[0]?.id||'';
 if(!analysisChannel(analysisState.compare)||analysisState.compare===analysisState.channel)analysisState.compare=analysisChannels().find(c=>c.id!==analysisState.channel&&c.titleCount>=5)?.id||'';
 const channels=analysisChannels(),withDur=channels.filter(c=>c.durationCount>0),videoN=arr(ANALYSIS.videos).length||channels.reduce((n,c)=>n+(c.videoCount||0),0),durN=channels.reduce((n,c)=>n+(c.durationCount||0),0);
 main.innerHTML=intro('SAMPLE ANALYSIS · RESEARCH EDITION','Patterns in the published record.','Compare video length, observed publication dates and recurring title vocabulary across publishing accounts. These are indexed samples assembled from the atlas and the supplied research ZIP.')+`<div class="analysis-top-links"><a href="analysis/report.html">Read the reviewed findings ↗</a><a href="analysis/channeling-atlas-paper.pdf" download>Working paper PDF ↓</a><a href="analysis/channeling-atlas-overleaf.zip" download>Overleaf source ZIP ↓</a><a href="analysis/channeling-analysis-bundle.zip" download>Download analysis bundle ↓</a></div><aside class="analysis-scope"><strong>What these comparisons measure</strong><p>Publishing choices and text in the collected records. A channel’s sample average is not its lifetime average; missing uploads are not measured. Of 881 usable durations, 877 were refreshed from watch metadata and four are labeled inherited observations. Titles, researcher summaries and original transcripts remain separate evidence layers.</p></aside><div class="yt-summary analysis-summary"><div><b>${channels.length}</b><span>account groups in the analysis</span></div><div><b>${videoN}</b><span>unique video records in this corpus</span></div><div><b>${withDur.length}</b><span>account groups with measured lengths</span></div><div><b>${durN}</b><span>channel-attributed duration records</span></div></div><div class="yt-tabs analysis-tabs" aria-label="Analysis views">${analysisTabs.map(([id,label])=>`<button type="button" data-analysis-tab="${id}" aria-pressed="${analysisState.tab===id}">${label}</button>`).join('')}</div><div id="analysis-results"></div>`;
 refreshAnalysis();
}
function analysisFiltered(){const q=analysisState.search.toLowerCase();const list=analysisChannels().filter(c=>(!q||[c.name,c.url,c.id].join(' ').toLowerCase().includes(q))&&(analysisState.coverage==='all'||(analysisState.coverage==='known'?c.durationCount>0:!c.durationCount)));return list.sort((a,b)=>{if(analysisState.sort==='name')return a.name.localeCompare(b.name);if(analysisState.sort==='sample')return b.videoCount-a.videoCount;const key=analysisState.sort==='median-desc'?'medianMinutes':'meanMinutes';return (b[key]??-1)-(a[key]??-1)||a.name.localeCompare(b.name)})}
function analysisTable(){const rows=analysisFiltered(),pages=Math.max(1,Math.ceil(rows.length/25));analysisState.page=Math.max(1,Math.min(analysisState.page,pages));const from=(analysisState.page-1)*25,pageRows=rows.slice(from,from+25);return `<div class="analysis-toolbar"><label><span>Find a publishing account</span><input type="search" id="analysis-search" placeholder="Search channel names…" value="${esc(analysisState.search)}"></label><label><span>Duration coverage</span><select id="analysis-coverage"><option value="all" ${analysisState.coverage==='all'?'selected':''}>All account groups</option><option value="known" ${analysisState.coverage==='known'?'selected':''}>At least one known length</option><option value="missing" ${analysisState.coverage==='missing'?'selected':''}>No known lengths</option></select></label><label><span>Sort rows</span><select id="analysis-sort">${[['duration-desc','Average length · longest first'],['median-desc','Median length · longest first'],['sample','Video sample · largest first'],['name','Account name · A–Z']].map(([id,label])=>`<option value="${id}" ${analysisState.sort===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="analysis-table-heading"><p role="status">${rows.length?from+1:0}–${Math.min(from+25,rows.length)} of ${rows.length} matching account groups · ${analysisChannels().length} total</p><a href="analysis/channel-metrics.csv" download>Download channel table CSV ↓</a></div><p class="analysis-caption">Table 1. Snapshot: ${esc(ANALYSIS.meta?.checkedAt||'2026-10-23')}. Lengths are in minutes. Mean, median and middle 50% use only indexed videos with a known duration. The coverage column gives known lengths / indexed videos for that account group. Dates count exact publication dates only. Unresolved values are shown as —.</p>${rows.length?`<div class="yt-table-scroll analysis-table-scroll" tabindex="0" aria-label="Scrollable channel statistics"><table class="yt-table analysis-table"><caption>Video duration and date coverage by publishing account</caption><thead><tr><th scope="col">Publishing account</th><th scope="col">Indexed videos</th><th scope="col">Length coverage</th><th scope="col">Average min</th><th scope="col">Median min</th><th scope="col">Middle 50% min</th><th scope="col">Exact dates</th></tr></thead><tbody>${pageRows.map(c=>`<tr><th scope="row"><button class="analysis-channel-link" data-analysis-channel="${esc(c.id)}">${esc(c.name)}</button>${c.url?`<a class="analysis-channel-url" href="${url(c.url)}" target="_blank" rel="noopener noreferrer">YouTube account ↗</a>`:''}</th><td>${c.videoCount||0}</td><td><strong>${c.durationCount||0} / ${c.videoCount||0}</strong><small>${c.videoCount?analysisPercent(c.durationCoverage)+' of this sample':'No indexed videos'}</small></td><td>${analysisNumber(c.meanMinutes)}</td><td>${analysisNumber(c.medianMinutes)}</td><td>${typeof c.q1Minutes==='number'?analysisNumber(c.q1Minutes)+'–'+analysisNumber(c.q3Minutes):'—'}</td><td>${c.dateCount||0}</td></tr>`).join('')}</tbody></table></div>`:empty('No account groups match these filters. Clear the search or change duration coverage.')}${rows.length>25?`<div class="discovery-pager analysis-pager"><button type="button" data-analysis-page="${analysisState.page-1}" ${analysisState.page===1?'disabled':''}>← Previous 25</button><span>Page ${analysisState.page} of ${pages}</span><button type="button" data-analysis-page="${analysisState.page+1}" ${analysisState.page>=pages?'disabled':''}>Next 25 →</button></div>`:''}<div class="analysis-reset"><button type="button" data-analysis-clear>Reset table filters</button></div>${analysisFigures(['duration','coverage'])}`}
function analysisBarChart(rows,{title,caption,unit='',format=String}={}){const max=Math.max(...rows.map(r=>Number(r.value)||0),1);return `<figure class="analysis-figure"><h3>${esc(title)}</h3>${rows.length?`<div class="analysis-bars" role="img" aria-label="${esc(title)}. Values are listed in the table below.">${rows.map(r=>`<div class="analysis-bar-row"><span>${esc(r.label)}</span><div><i style="width:${Math.max(0,100*(Number(r.value)||0)/max)}%"></i></div><b>${esc(format(r.value))}${esc(unit)}</b></div>`).join('')}</div><details class="analysis-data"><summary>View chart data</summary><table><thead><tr><th scope="col">Category</th><th scope="col">Value${unit?' ('+esc(unit)+')':''}</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.label)}</th><td>${esc(format(r.value))}</td></tr>`).join('')}</tbody></table></details>`:'<p class="analysis-empty">No observations are available for this chart.</p>'}<figcaption>${esc(caption)}</figcaption></figure>`}
function analysisSourceText(value){if(value==null)return 'See contributing record provenance';if(typeof value==='string')return value.replaceAll('_',' ');if(Array.isArray(value))return value.map(analysisSourceText).join(' · ');return Object.entries(value).map(([k,v])=>k.replaceAll('_',' ')+': '+v).join(' · ')}
function analysisSemanticChart(c){if(!ANALYSIS.semanticSimilarity)return '';const s=ANALYSIS.semanticSimilarity,pairs=arr(s.pairs).filter(p=>p.a===c.id||p.b===c.id).sort((a,b)=>b.cosine-a.cosine).slice(0,5);return analysisBarChart(pairs.map(p=>({label:analysisLabel(p.a===c.id?p.b:p.a)+' (n='+String(p.a===c.id?p.nB:p.nA)+')',value:p.cosine})),{title:'Nearest learned title embeddings',format:v=>analysisNumber(v,3),caption:`Figure C5. ${s.method||'Learned sentence-embedding'} cosine similarity between equally weighted title centroids; at least ${s.minTitles||5} eligible titles per account. ${s.identityMasked?'The documented name-and-genre terms are masked.':'See preprocessing in model provenance.'} The same words can influence both lexical and learned vectors. These scores are not probabilities of agreement or independent validation. Snapshot: ${ANALYSIS.meta?.checkedAt||'2026-10-23'}.`})}
function analysisMaskLabel(value){return String(value||'').replaceAll('common channeling identity terms','the documented name-and-genre term list').replaceAll('Common identity words are masked.','The documented name-and-genre terms are masked.').replaceAll('identity-masked','name-and-genre-masked').replaceAll('Identity masking','Name-and-genre masking')}
function analysisMatchedCohort(){const s=ANALYSIS.matchedTitleSimilarity;if(!s)return '';const pairs=arr(s.pairs),counts=new Map();pairs.forEach(p=>{counts.set(p.a,Number(p.nA)||0);counts.set(p.b,Number(p.nB)||0)});const contributing=[...counts.values()].reduce((sum,n)=>sum+n,0);return `<p class="analysis-caption"><strong>Matched comparison:</strong> ${s.documentCount||0} videos are eligible for title/caption comparison; ${contributing} contributing videos from ${counts.size} accounts produce ${pairs.length} dependent account pairs after the minimum of ${s.minTitles||2} videos per account. The vocabulary-presence analysis uses the broader eligible set. <a href="analysis/channeling-atlas-paper.pdf">Read the working paper for the matched analysis ↗</a></p>`}
function analysisTranscriptSection(channel){const t=ANALYSIS.transcripts;if(!t)return `<section class="analysis-transcript-section"><span class="eyebrow">TRANSCRIPT ACCESS</span><h3>No transcript analysis in this data release.</h3><p>Title wording and researcher summaries are not substituted for original transcripts.</p></section>`;const rows=arr(t.rows).filter(r=>!channel||r.channelId===channel.id),retrieved=channel?channel.retrievedCount:t.available,pilot=channel?channel.transcriptCount:t.englishPilotCount,words=rows.reduce((n,r)=>n+(Number(r.wordCount)||0),0),rates=channel?arr(channel.transcriptTopics):[];return `<section class="analysis-transcript-section"><span class="eyebrow">SEPARATE TEXT LAYER · CAPTION PILOT</span><h3>${channel?'Captions available for this account':'What the caption pilot can support'}</h3><p>${channel?`For ${esc(channel.name)}, ${typeof retrieved==='number'?retrieved+' caption documents were retrieved; ':''}${pilot||0} are included in the English analysis pilot.`:`${t.available||0} caption documents were retrieved from ${t.attempted||0} attempted videos. ${t.englishPilotCount||0} English documents are included in this pilot. Retrieved documents excluded by language or selection rules are not counted in its topic and vector comparisons.`} Captions can contain recognition errors, incomplete speech or incorrect speaker segmentation.</p><div class="analysis-transcript-stats"><span><b>${rows.length}</b> included documents</span><span><b>${words.toLocaleString('en-US')}</b> alphabetic words</span><span><b>${new Set(rows.map(r=>r.channelId).filter(Boolean)).size}</b> attributed account groups</span></div>${!channel?analysisMatchedCohort():''}${t.method?`<p class="analysis-caption">${esc(t.method)} ${esc(t.tokenization||'')}</p>`:''}${channel&&rates.length?analysisBarChart(rates.map(r=>({label:r.label,value:r.per1000Words})),{title:'Keyword occurrences in caption text',format:v=>analysisNumber(v,2),caption:`Figure C6. Occurrences of codebook keywords per 1,000 alphabetic words in ${rows.length} included English caption documents for ${channel.name}. This differs from the percentage-of-titles measure: keyword occurrences are normalized per video, then averaged equally across the account’s included videos; repeated keywords count repeatedly. Caption errors and the small selected sample limit interpretation. Snapshot: ${ANALYSIS.meta?.checkedAt||'2026-10-23'}.`}):!rows.length?'<p class="analysis-empty">No included English caption document is available for this account in the current pilot. Its title comparisons remain a separate source layer.</p>':''}<details class="analysis-data"><summary>Inspect ${rows.length} included caption documents</summary>${rows.length?`<div class="yt-table-scroll"><table><caption>Caption acquisition and analysis provenance</caption><thead><tr><th scope="col">Source video</th><th scope="col">Account</th><th scope="col">Language / caption type</th><th scope="col">Words</th><th scope="col">Selection</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row"><a href="${url(r.url)}" target="_blank" rel="noopener noreferrer">${esc(arr(ANALYSIS.videos).find(v=>v.id===r.videoId)?.title||r.videoId)} ↗</a></th><td>${esc(analysisLabel(r.channelId)||'Unresolved')}</td><td>${esc(r.language||'Unresolved')} · ${r.automaticCaptions===true?'Automatic captions':r.automaticCaptions===false?'Source-provided captions':'Caption type unresolved'}</td><td>${Number(r.wordCount)||0}</td><td>${esc(analysisSourceText(r.selection))}</td></tr>`).join('')}</tbody></table></div>`:'<p>No included transcript rows for this selection.</p>'}</details><div class="analysis-figure-links"><a class="analysis-download-figure" href="analysis/caption-documents.csv" download>Caption document metadata CSV ↓</a><a class="analysis-download-figure" href="analysis/caption-topic-indicators.csv" download>Caption keyword measures CSV ↓</a><a class="analysis-download-figure" href="analysis/caption-similarity-pairs.csv" download>Caption similarity CSV ↓</a></div><p class="analysis-caption">Source text is represented by acquisition metadata and derived measures in these exports. Word patterns do not authenticate ET contact or verify the source of a claimed message. Different people speaking within the same video are not automatically separated by this analysis.</p></section>`}

function analysisChannelView(){const c=analysisChannel(analysisState.channel);if(!c)return empty('No channel-level observations are available.');const topics=(c.titleCount?arr(c.topics):[]).sort((a,b)=>b.count-a.count),months=arr(c.monthly),videos=arr(ANALYSIS.videos).filter(v=>v.channelId===c.id||arr(v.channelIds).includes(c.id)),pairs=arr(ANALYSIS.similarity?.pairs).filter(p=>p.a===c.id||p.b===c.id).sort((a,b)=>b.cosine-a.cosine).slice(0,5);return `<div class="analysis-selector"><label for="analysis-channel">Choose a publishing account</label><select id="analysis-channel">${analysisOptions(c.id)}</select></div><section class="analysis-channel-head"><span class="eyebrow">SELECTED ACCOUNT · ${c.videoCount||0} INDEXED VIDEOS</span><h2>${esc(c.name)}</h2>${c.url?`<a class="text-link" href="${url(c.url)}" target="_blank" rel="noopener noreferrer">Open the publishing account ↗</a>`:''}${c.sourceStatus||c.durationSourceSummary?`<p class="analysis-source-summary">Sources: ${esc(analysisSourceText(c.sourceStatus))}. Duration observations: ${esc(analysisSourceText(c.durationSourceSummary))}.</p>`:''}<div class="analysis-detail-actions"><button type="button" data-analysis-export-channel="${esc(c.id)}">Download this account’s video CSV ↓</button><button type="button" data-analysis-tab="compare">Compare this account ↗</button></div><div class="analysis-metrics"><div><span>Average observed length</span><b>${analysisNumber(c.meanMinutes)} <small>min</small></b></div><div><span>Median observed length</span><b>${analysisNumber(c.medianMinutes)} <small>min</small></b></div><div><span>Duration coverage</span><b>${c.durationCount||0}<small> / ${c.videoCount||0}</small></b></div><div><span>Exact publication dates</span><b>${c.dateCount||0}<small> / ${c.videoCount||0}</small></b></div></div><p class="analysis-caption">Measurements describe the indexed sample for this account. ${!c.durationCount?'No known video lengths are available in this sample. ':c.durationCount===1?'One observed video: its duration is both the mean and median; this is not a stable account estimate. ':c.durationCount<5?'Fewer than five known lengths: treat the mean and median as individual-record descriptions, not stable estimates. ':''}${c.dateCount<2?'Insufficient exact dates to characterize a publication pattern. ':''}A publishing account can contain reposts, interviews, multiple speakers or narrated material.</p></section><div class="analysis-figure-grid">${analysisBarChart((c.durationCount?arr(c.durationBins):[]).map(b=>({label:b.label,value:b.count})),{title:'Observed video lengths',caption:`Figure C1. Duration distribution for ${c.name}; ${c.durationCount||0} known lengths out of ${c.videoCount||0} indexed videos. Bins are counted once per video. Missing lengths are excluded. Snapshot: ${ANALYSIS.meta?.checkedAt||'2026-10-23'}.`})}${analysisBarChart(months.map(m=>({label:m.month,value:m.count})),{title:'Indexed uploads by month',caption:`Figure C2. Exact-date records in ${c.name}'s indexed sample (${c.dateCount||0} videos). These counts describe collected records, not a complete publishing schedule. An empty or low month can reflect collection gaps. Snapshot: ${ANALYSIS.meta?.checkedAt||'2026-10-23'}.`})}${analysisBarChart(topics.map(t=>({label:t.label,value:t.share})),{title:'Topics appearing in titles',unit:'%',format:v=>String(Math.round(Number(v)*100)),caption:`Figure C3. Keyword-codebook matches as a share of ${c.titleCount||0} English-likely eligible titles for ${c.name}. A title may match multiple topics. This uses an English keyword dictionary and can miss other languages or implicit wording; it is not a transcript-level estimate of content. Snapshot: ${ANALYSIS.meta?.checkedAt||'2026-10-23'}.`})}${analysisBarChart(pairs.map(p=>({label:analysisLabel(p.a===c.id?p.b:p.a)+' (n='+String(p.a===c.id?p.nB:p.nA)+')',value:p.cosine})),{title:'Nearest title vocabularies',format:v=>analysisNumber(v,3),caption:`Figure C4. Cosine similarity from ${ANALYSIS.similarity?.method||'TF–IDF title vectors'}. Only account groups meeting the minimum of ${ANALYSIS.similarity?.minTitles||5} eligible titles are compared. Shared language can arise from naming, reposting or editorial style; this is not evidence of shared origins or independent agreement. Snapshot: ${ANALYSIS.meta?.checkedAt||'2026-10-23'}.`})}${analysisSemanticChart(c)}</div>${arr(c.topTerms).length?`<section class="analysis-word-list"><h3>Distinctive title terms</h3><p>${arr(c.topTerms).map(t=>esc(typeof t==='string'?t:t.term||t.label||'')).filter(Boolean).join(' · ')}</p><p class="analysis-caption">Highest-weight terms in the account’s TF–IDF title representation. Names and boilerplate can influence this list.</p></section>`:''}${analysisTranscriptSection(c)}${videos.length?`<details class="analysis-data analysis-video-details"><summary>Inspect ${videos.length} contributing video records</summary><div class="yt-table-scroll"><table class="yt-table"><caption>Source video observations for ${esc(c.name)}</caption><thead><tr><th scope="col">Video</th><th scope="col">Length</th><th scope="col">Publication date</th><th scope="col">Evidence layer</th></tr></thead><tbody>${videos.map(v=>`<tr><th scope="row"><a href="${url(v.url||v.videoUrl)}" target="_blank" rel="noopener noreferrer">${esc(v.title||v.id||v.videoId)} ↗</a></th><td>${analysisNumber(v.durationMinutes??(typeof v.durationSeconds==='number'?v.durationSeconds/60:null))} min</td><td>${esc(v.date||v.publishedAt||v.publishedDate||'Unresolved')}</td><td>${esc([v.titleSource&&'Title: '+v.titleSource,v.durationSource&&'Duration: '+v.durationSource,v.dateSource&&'Date: '+v.dateSource].filter(Boolean).join(' · ')||v.textLayer||v.accessDepth||v.evidenceStatus||'Supplied / indexed metadata')}</td></tr>`).join('')}</tbody></table></div></details>`:''}`}
function analysisPairRecord(obj,a,b){return arr(obj?.pairs).find(p=>(p.a===a&&p.b===b)||(p.a===b&&p.b===a))}
function analysisPairSample(obj,a,b){const p=analysisPairRecord(obj,a,b);return p?'Model-eligible titles: '+(p.a===a?p.nA:p.nB)+' / '+(p.a===a?p.nB:p.nA):'No eligible model comparison for this pair'}
function analysisPairValue(obj,a,b){const p=arr(obj?.pairs).find(p=>(p.a===a&&p.b===b)||(p.a===b&&p.b===a));if(p)return p.cosine;const ids=arr(obj?.channelIds),i=ids.indexOf(a),j=ids.indexOf(b);return i>=0&&j>=0?obj.matrix?.[i]?.[j]:null}
function analysisCompare(){const a=analysisChannel(analysisState.channel),b=analysisChannel(analysisState.compare);if(!a||!b)return empty('At least two attributed account groups are needed for comparison.');const topics=arr(ANALYSIS.topics),left=new Map(arr(a.topics).map(t=>[t.id,t])),right=new Map(arr(b.topics).map(t=>[t.id,t])),rows=(topics.length?topics:arr(a.topics)).map(t=>({label:t.label,id:t.id,a:a.titleCount?(left.get(t.id)?.share??0):null,b:b.titleCount?(right.get(t.id)?.share??0):null})),lex=analysisPairValue(ANALYSIS.similarity,a.id,b.id),sem=analysisPairValue(ANALYSIS.semanticSimilarity,a.id,b.id);return `<div class="analysis-compare-selectors"><label><span>First account</span><select id="analysis-channel">${analysisOptions(a.id)}</select></label><label><span>Second account</span><select id="analysis-compare">${analysisOptions(b.id,a.id)}</select></label></div><section class="analysis-comparison-note"><h2>Shared words, different samples.</h2><p>Compare the proportion of collected titles matching the same transparent keyword categories. ${esc(a.name)} has ${a.titleCount||0} English-likely eligible titles; ${esc(b.name)} has ${b.titleCount||0}. These denominators can differ substantially. Titles must pass a heuristic language check and contain at least four alphabetic words; short and multilingual titles can be excluded.</p><div class="analysis-pair-scores"><div><span>Lexical cosine similarity</span><b>${analysisNumber(lex,3)}</b><small>${esc(ANALYSIS.similarity?.method||'TF–IDF title vectors')}<br>${esc(analysisPairSample(ANALYSIS.similarity,a.id,b.id))}</small></div>${ANALYSIS.semanticSimilarity?`<div><span>Learned-embedding cosine similarity</span><b>${analysisNumber(sem,3)}</b><small>${esc(ANALYSIS.semanticSimilarity.method||'See model provenance')}<br>${esc(analysisPairSample(ANALYSIS.semanticSimilarity,a.id,b.id))}</small></div>`:'<p>No learned-embedding score is displayed unless a model run is available in this release. TF–IDF is a lexical vector representation.</p>'}</div><p class="analysis-caption">Cosine values are descriptive model outputs, not calibrated probabilities or evidence that independent messages agree. — indicates insufficient eligible data or an unavailable comparison.</p></section><figure class="analysis-figure analysis-comparison-figure"><h3>Title topic prevalence</h3><div class="analysis-legend"><span><i></i>${esc(a.name)} · n=${a.titleCount||0}</span><span><i></i>${esc(b.name)} · n=${b.titleCount||0}</span></div><div class="analysis-paired-bars">${rows.map(r=>`<div class="analysis-paired-row"><strong>${esc(r.label)}</strong><div><i style="width:${Math.min(100,r.a*100)}%"></i><span>${analysisPercent(r.a)}</span></div><div><i style="width:${Math.min(100,r.b*100)}%"></i><span>${analysisPercent(r.b)}</span></div></div>`).join('')}</div><figcaption>Figure 2. Share of eligible titles with at least one codebook keyword match, by account. The axis runs from 0% to 100%; multiple categories may match one title, so totals need not sum to 100%. Absence of a keyword does not establish absence of the topic in a video. Compare text access and language before interpreting differences.</figcaption><details class="analysis-data"><summary>View comparison data</summary><table><thead><tr><th scope="col">Topic</th><th scope="col">${esc(a.name)}</th><th scope="col">${esc(b.name)}</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r.label)}</th><td>${analysisPercent(r.a)}</td><td>${analysisPercent(r.b)}</td></tr>`).join('')}</tbody></table></details></figure>${analysisFigures(['topic','similarity','sensitivity','robust'],['caption'])}${analysisTranscriptSection()}${analysisFigures(['caption'])}`}
function analysisFigureDataPath(f){return analysisSafePath(f.dataPath)||'analysis/'+(f.id==='duration'||f.id==='coverage'?'channel-metrics.csv':f.id.includes('caption')?(f.id.includes('topic')?'caption-topic-indicators.csv':'caption-similarity-pairs.csv'):f.id.includes('semantic')?'semantic-title-pairs.csv':f.id.includes('topic')?'title-topic-indicators.csv':'title-similarity-pairs.csv')}
function analysisFigures(keys,exclude=[]){return arr(ANALYSIS.figures).filter(f=>keys.some(k=>String(f.id).includes(k))&&!exclude.some(k=>String(f.id).includes(k))).map(f=>{const path=analysisSafePath(f.path);return path?`<figure class="analysis-figure analysis-export-figure"><h3>${esc(f.title)}</h3><a href="${esc(path)}" target="_blank" rel="noopener"><img src="${esc(path)}" alt="${esc(f.alt||f.title)}" loading="lazy"></a><figcaption>${esc(analysisMaskLabel(f.caption))} Snapshot: ${esc(ANALYSIS.meta?.checkedAt||'2026-10-23')}.</figcaption><div class="analysis-figure-links"><a class="analysis-download-figure" href="${esc(path)}" download>Download figure ↓</a><a class="analysis-download-figure" href="${esc(analysisFigureDataPath(f))}" download>Underlying data CSV ↓</a></div></figure>`:''}).join('')}
function analysisMethods(){const limits=arr(ANALYSIS.limitations);return `<section class="analysis-method-copy"><span class="eyebrow">READ THE MEASURE BEFORE THE PATTERN</span><h2>What was measured.</h2><p>The uploaded ZIP and the existing atlas supply linked records with different inspection depths. The analysis joins exact video identifiers, retains account attribution and reports coverage before calculating statistics. The source record, not its inclusion here, determines whether text is a title, summary or transcript.</p><dl><dt>Duration</dt><dd>Arithmetic mean, median and quartiles describe available lengths within each account’s indexed sample. Means are sensitive to long sessions and mixed short/long formats.</dd><dt>Publication pattern</dt><dd>Monthly counts use exact dates only. Relative dates and unresolved dates stay outside the exact-date chart. The collection is not a channel census, so upload rates and gaps cannot be generalized.</dd><dt>Title topics</dt><dd>Transparent keyword groups create multi-label title counts. Shares use the eligible-title denominator for that account. Topic words in titles can reflect promotion or editorial choices.</dd><dt>Vector comparisons</dt><dd>Lexical TF–IDF vectors compare word use. The documented name-and-genre mask removes selected practitioner/entity names and channeling-related vocabulary. Learned embeddings have separate model and run provenance. Proximity is a text-pattern observation; it does not authenticate a speaker, an entity, a prediction or healing claims.</dd></dl>${limits.length?`<details class="analysis-data"><summary>Inspect the title-topic keyword codebook</summary><table><thead><tr><th scope="col">Topic</th><th scope="col">Matching rule</th></tr></thead><tbody>${arr(ANALYSIS.topics).map(t=>`<tr><th scope="row">${esc(t.label)}</th><td><code>${esc(t.regex||arr(t.keywords).join(', '))}</code></td></tr>`).join('')}</tbody></table></details><h3>Known limitations</h3><ul>${limits.map(x=>`<li>${esc(typeof x==='string'?x:x.message||x.description||JSON.stringify(x))}</li>`).join('')}</ul>`:''}<div class="analysis-download-list"><a class="button" href="analysis/report.html">Read the research report ↗</a><a href="analysis/channeling-atlas-paper.pdf" download>Working paper PDF ↓</a><a href="analysis/channeling-atlas-overleaf.zip" download>Overleaf source ZIP ↓</a><a href="analysis/channeling-analysis-bundle.zip" download>Complete analysis bundle ZIP ↓</a><a href="analysis/data.json" download>Analysis data JSON ↓</a><a href="analysis/channel-metrics.csv" download>Channel statistics CSV ↓</a><a href="analysis/video-observations.csv" download>Video observations CSV ↓</a><a href="analysis/monthly-indexed-counts.csv" download>Indexed monthly counts CSV ↓</a><a href="analysis/title-topic-indicators.csv" download>Title topic frequencies CSV ↓</a><a href="analysis/title-similarity-pairs.csv" download>Lexical title comparisons CSV ↓</a>${ANALYSIS.semanticSimilarity?'<a href="analysis/semantic-title-pairs.csv" download>Learned title comparisons CSV ↓</a>':''}</div><details class="analysis-data"><summary>Original snapshot metadata and model provenance</summary><p>The original snapshot uses the label “identity masking” for the documented name-and-genre mask.</p><pre>${esc(JSON.stringify({meta:ANALYSIS.meta,coverage:ANALYSIS.coverage,similarity:{method:ANALYSIS.similarity?.method,minTitles:ANALYSIS.similarity?.minTitles},semanticSimilarity:ANALYSIS.semanticSimilarity?{method:ANALYSIS.semanticSimilarity.method,model:ANALYSIS.semanticSimilarity.model,minTitles:ANALYSIS.semanticSimilarity.minTitles}:null,transcripts:ANALYSIS.transcripts?{attempted:ANALYSIS.transcripts.attempted,available:ANALYSIS.transcripts.available,englishPilotCount:ANALYSIS.transcripts.englishPilotCount,captionLanguages:ANALYSIS.transcripts.captionLanguages,method:ANALYSIS.transcripts.method,tokenization:ANALYSIS.transcripts.tokenization,topicDefinition:ANALYSIS.transcripts.topicDefinition}:null,robustness:ANALYSIS.robustness},null,2))}</pre></details></section>${analysisTranscriptSection()}${analysisFigures(['corpus','text','embedding'])}`}
function exportAnalysisChannel(id){const c=analysisChannel(id);if(!c)return;const rows=arr(ANALYSIS.videos).filter(v=>v.channelId===id||arr(v.channelIds).includes(id));const headers=['Video ID','Title','Video URL','Publisher account','Account URL','Duration seconds','Publication date','Title eligible','Title source','Duration source','Date source','People attribution','Claimed entities','Conflicts','Provenance'];triggerDownload('channeling-analysis-'+id+'.csv',csvBody(headers,rows.map(v=>[v.id,v.title,v.url,c.name,c.url,v.durationSeconds,v.date,v.titleEligible,v.titleSource,v.durationSource,v.dateSource,arr(v.people),arr(v.entities),JSON.stringify(v.conflicts||[]),JSON.stringify(v.provenance||[])])),'text/csv;charset=utf-8')}
function refreshAnalysis(){const target=document.querySelector('#analysis-results');if(!target||!ANALYSIS)return;document.querySelectorAll('[data-analysis-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.analysisTab===analysisState.tab)));target.innerHTML=analysisState.tab==='channels'?analysisTable():analysisState.tab==='channel'?analysisChannelView():analysisState.tab==='compare'?analysisCompare():analysisMethods()}
main.addEventListener('input',e=>{if(e.target.id==='analysis-search'){analysisState.search=e.target.value;analysisState.page=1;const pos=e.target.selectionStart;refreshAnalysis();const search=document.querySelector('#analysis-search');search?.focus();search?.setSelectionRange(pos,pos)}});
main.addEventListener('change',e=>{if(!e.target.id.startsWith('analysis-'))return;const key=e.target.id.slice(9);if(key in analysisState){analysisState[key]=e.target.value;if(['sort','coverage'].includes(key))analysisState.page=1;if(key==='channel'&&analysisState.channel===analysisState.compare)analysisState.compare=analysisChannels().find(c=>c.id!==analysisState.channel)?.id||'';refreshAnalysis()}});
main.addEventListener('click',e=>{const tab=e.target.closest('[data-analysis-tab]'),channel=e.target.closest('[data-analysis-channel]');if(tab){analysisState.tab=tab.dataset.analysisTab;refreshAnalysis()}if(channel){analysisState.channel=channel.dataset.analysisChannel;analysisState.tab='channel';refreshAnalysis();document.querySelector('#analysis-results')?.scrollIntoView({block:'start',behavior:'instant'})}if(e.target.closest('[data-analysis-clear]')){Object.assign(analysisState,{search:'',coverage:'all',page:1});refreshAnalysis()}const exported=e.target.closest('[data-analysis-export-channel]');if(exported)exportAnalysisChannel(exported.dataset.analysisExportChannel);const page=e.target.closest('[data-analysis-page]');if(page&&!page.disabled){analysisState.page=Number(page.dataset.analysisPage);refreshAnalysis();document.querySelector('#analysis-results')?.scrollIntoView({block:'start',behavior:'instant'})}if(e.target.closest('[data-analysis-retry]'))analysis()});

const views={overview,profiles,timeline,entities,communities,videos,sources,method,youtube,sessions,discovery,analysis};
function renderRoute(){
 if(location.hash==='#main'){main.focus();return;}
 const raw=(location.hash||'#/overview').replace(/^#\/?/,''),[path,query='']=raw.split('?'),bits=path.split('/'),params=new URLSearchParams(query);
 const view=views[bits[0]]?bits[0]:'overview',kind=view==='youtube'?bits[1]:null,id=view==='youtube'?(bits[2]?decodeURIComponent(bits[2]):null):(bits[1]?decodeURIComponent(bits[1]):null),previousView=currentView;
 currentView=view;
 if(view==='youtube'&&params.has('profile'))ytState.profile=params.get('profile');
 if(view==='youtube'&&params.has('date'))ytState.date=['year','month','known','unknown'].includes(params.get('date'))?params.get('date'):'';
 if(view==='youtube'&&params.has('tab')&&['videos','accounts','coverage'].includes(params.get('tab')))ytState.tab=params.get('tab');
 if(view==='discovery'&&params.has('person'))discoveryState.person=params.get('person');
 if(view==='discovery'&&params.has('tab')&&['all','account','playlist','video','people','queries'].includes(params.get('tab')))discoveryState.tab=params.get('tab');
 if(view==='analysis'&&params.has('channel')){analysisState.channel=params.get('channel');analysisState.tab='channel';}
 if(view==='analysis'&&params.has('tab')&&['channels','channel','compare','method'].includes(params.get('tab')))analysisState.tab=params.get('tab');
 const bodySelector=view==='analysis'?'#analysis-results':view==='youtube'?'#yt-results':view==='sessions'?'#session-results':view==='discovery'?'#discovery-results':'#results';
 if(!id||view!==previousView||!document.querySelector(bodySelector)){state.search='';state.filter='';state.year='';views[view]();}
 document.querySelectorAll('.main-nav a').forEach(a=>{if(a.hash==='#/'+view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 document.title=`${({overview:'People, stories & source records',profiles:'People & channels',timeline:'Historical timeline',entities:'Entities & traditions',communities:'Community discussions',videos:'Watch & listen',sources:'Source library',method:'Research method',youtube:'YouTube account & video index',sessions:'Yearly activity & session prices',discovery:'Expanded channeling discovery',analysis:'Channel samples & topic analysis'})[view]} — Channeling Atlas`;
 let record,detail;
 if(id&&view==='profiles'){record=profileMap.get(id);if(record)detail=profileDetail(record)}
 if(id&&view==='sources'){record=sourceMap.get(id);if(record)detail=sourceDetail(record)}
 if(id&&view==='youtube'&&['account','video'].includes(kind)){record=(kind==='account'?ytAccounts():ytVideos()).find(x=>x.id===id);if(record)detail=youtubeDetail(record,kind)}
 if(detail){returnRoute='#/'+view+(view==='youtube'&&ytState.profile?'?profile='+encodeURIComponent(ytState.profile):'');dialogBody.innerHTML=detail;if(!dialog.open)dialog.showModal();document.body.classList.add('dialog-open');dialog.scrollTop=0;return;}
 if(dialog.open){changingDialog=true;dialog.close();changingDialog=false;}document.body.classList.remove('dialog-open');window.scrollTo({top:0,behavior:'instant'});
}
function closeDialog(){location.hash=returnRoute;}
document.querySelector('#close-dialog').addEventListener('click',closeDialog);dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});dialog.addEventListener('close',()=>{document.body.classList.remove('dialog-open');if(!changingDialog&&location.hash.split('/').length>2)closeDialog()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});
main.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;refresh()}});main.addEventListener('change',e=>{if(e.target.id==='filter'||e.target.id==='year'){state[e.target.id]=e.target.value;refresh()}});
function refresh(){({profiles:refreshProfiles,timeline:refreshTimeline,entities:refreshEntities,communities:refreshCommunities,videos:refreshVideos,sources:refreshSources}[currentView]||(()=>{}))()}
window.addEventListener('hashchange',renderRoute);
fetch('data.json').then(r=>{if(!r.ok)throw Error('Research records could not be loaded.');return r.json()}).then(data=>{DATA={...DATA,...data};['profiles','events','sources','entities','communityItems','videoItems','insights','services'].forEach(k=>{if(!Array.isArray(DATA[k]))DATA[k]=[]});if(!DATA.youtube||Array.isArray(DATA.youtube))DATA.youtube={accounts:[],videos:[],gaps:[],meta:{}};['accounts','videos','gaps'].forEach(k=>{if(!Array.isArray(DATA.youtube[k]))DATA.youtube[k]=[]});if(!DATA.activity||Array.isArray(DATA.activity))DATA.activity={records:[],meta:{}};if(!Array.isArray(DATA.activity.records))DATA.activity.records=[];if(!DATA.discovery||Array.isArray(DATA.discovery))DATA.discovery={meta:{},people:[],records:[],queries:[],gaps:[]};['people','records','queries','gaps'].forEach(k=>{if(!Array.isArray(DATA.discovery[k]))DATA.discovery[k]=[]});DATA.sources.forEach((s,i)=>{s.index=i+1;sourceMap.set(s.id,s)});DATA.profiles.forEach(p=>profileMap.set(p.id,p));renderRoute()}).catch(error=>{main.innerHTML=`<div class="loading"><span class="eyebrow">RESEARCH RECORDS UNAVAILABLE</span><h1>The atlas could not open.</h1><p>${esc(error.message)} Please reload this page.</p><a class="text-link" href="data.json">Open the research data directly ↗</a></div>`});
